css:
.bkt-marquee {
  --bkt-marquee-bg: oklch(97.4% 0.012 82);
  --bkt-marquee-ink: oklch(23% 0.02 60);
  --bkt-marquee-accent: oklch(54% 0.11 152);
  --bkt-marquee-card: oklch(99.4% 0.005 82);
  --bkt-marquee-muted: color-mix(in oklch, var(--bkt-marquee-ink) 58%, var(--bkt-marquee-bg));
  --bkt-marquee-line: color-mix(in oklch, var(--bkt-marquee-ink) 10%, transparent);
  --bkt-marquee-tint: color-mix(in oklch, var(--bkt-marquee-accent) 22%, transparent);
  --bkt-marquee-gutter: clamp(16px, 5cqi, 64px);
  --bkt-marquee-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  --bkt-marquee-out: cubic-bezier(.22, .9, .3, 1);
  container-type: inline-size;
  container-name: bkt-marquee;
  box-sizing: border-box;
  width: 100%;
  overflow: hidden;
  background: var(--bkt-marquee-bg);
  color: var(--bkt-marquee-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dd, ul, figure, blockquote) { margin: 0; padding: 0; }
}

.bkt-marquee-in { padding-block: clamp(32px, 5.5cqi, 68px); display: grid; gap: clamp(22px, 3.4cqi, 40px); }

.bkt-marquee-head {
  padding-inline: var(--bkt-marquee-gutter);
  display: grid;
  gap: 14px 40px;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "eyebrow ctl" "title title" "lede lede" "stats stats";
  align-items: center;
}
.bkt-marquee-eyebrow {
  grid-area: eyebrow;
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; letter-spacing: .01em;
  color: var(--bkt-marquee-muted);
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkt-marquee-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & b { color: var(--bkt-marquee-ink); font-weight: 650; letter-spacing: -.01em; font-size: 14.5px; }
}
.bkt-marquee-title {
  grid-area: title;
  font-size: clamp(30px, 4.4cqi + 12px, 58px);
  line-height: 1.02;
  letter-spacing: -.035em;
  font-weight: 640;
  text-wrap: balance;
  max-width: 16ch;
}
.bkt-marquee-lede {
  grid-area: lede;
  max-width: 46ch;
  color: var(--bkt-marquee-muted);
  font-size: clamp(15px, .6cqi + 12px, 17.5px);
  text-wrap: pretty;
}
.bkt-marquee-stats {
  grid-area: stats;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--bkt-marquee-line);
  margin-top: 6px;
  & > div { padding: 14px 12px 0 0; display: flex; flex-direction: column-reverse; gap: 2px; }
  & > div + div { padding-left: 14px; border-left: 1px solid var(--bkt-marquee-line); }
  & dt { font-size: 11.5px; color: var(--bkt-marquee-muted); letter-spacing: .02em; }
  & dd { font-size: clamp(22px, 1.6cqi + 14px, 32px); font-weight: 600; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & small { font-size: .5em; color: var(--bkt-marquee-muted); font-weight: 500; letter-spacing: 0; margin-left: 1px; }
}
.bkt-marquee-ctl {
  grid-area: ctl;
  justify-self: end;
  display: inline-flex; align-items: center; gap: 7px;
  font: inherit; font-size: 13px; font-weight: 500; line-height: 1;
  color: var(--bkt-marquee-ink);
  background: var(--bkt-marquee-card);
  border: 1px solid var(--bkt-marquee-line);
  border-radius: 999px;
  padding: 8px 14px 8px 11px;
  cursor: pointer;
  transition: background-color .2s, border-color .2s, scale .35s var(--bkt-marquee-spring);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & .bkt-marquee-i-play { display: none; fill: currentColor; stroke-width: 1.4; }
  &:hover { background: color-mix(in oklch, var(--bkt-marquee-accent) 8%, var(--bkt-marquee-card)); border-color: color-mix(in oklch, var(--bkt-marquee-accent) 40%, transparent); }
  &:active { scale: .96; }
  &:focus-visible { outline: 2px solid var(--bkt-marquee-accent); outline-offset: 3px; }
}
.bkt-marquee.is-held .bkt-marquee-ctl {
  & .bkt-marquee-i-pause { display: none; }
  & .bkt-marquee-i-play { display: inline; }
}

.bkt-marquee-rows { display: grid; gap: 4px; }
.bkt-marquee-row {
  overflow: hidden;
  padding-block: 12px 18px;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 7%, #000 93%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 7%, #000 93%, transparent);
}
.bkt-marquee-track { display: flex; width: max-content; will-change: transform; }
.bkt-marquee-set {
  display: flex; gap: 16px; padding-inline-end: 16px;
  list-style: none;
}
.bkt-marquee-card {
  width: clamp(268px, 22cqi + 120px, 344px);
  flex: none;
  display: flex;
  transition: opacity .45s var(--bkt-marquee-out), filter .45s var(--bkt-marquee-out), translate .55s var(--bkt-marquee-spring), box-shadow .45s var(--bkt-marquee-out);
  border-radius: 18px;
  background: var(--bkt-marquee-card);
  border: 1px solid var(--bkt-marquee-line);
  box-shadow: 0 1px 0 color-mix(in oklch, var(--bkt-marquee-ink) 4%, transparent), 0 8px 24px -18px color-mix(in oklch, var(--bkt-marquee-ink) 30%, transparent);
  & figure { display: flex; flex-direction: column; gap: 14px; padding: 18px 20px 18px; width: 100%; }
  & blockquote { flex: 1; font-size: 15px; line-height: 1.5; letter-spacing: -.005em; text-wrap: pretty; }
  & mark { color: inherit; background: linear-gradient(transparent 58%, var(--bkt-marquee-tint) 58%, var(--bkt-marquee-tint) 92%, transparent 92%); padding-inline: 1px; }
  & figcaption { display: flex; align-items: center; gap: 10px; padding-top: 14px; border-top: 1px dashed var(--bkt-marquee-line); }
}
.bkt-marquee-tag {
  font-size: 10.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;
  color: oklch(46% 0.08 var(--h));
}
.bkt-marquee-av {
  flex: none; width: 34px; height: 34px; border-radius: 50%;
  display: grid; place-items: center;
  font-size: 11.5px; font-weight: 650; letter-spacing: .02em;
  color: oklch(34% 0.09 var(--h));
  background: radial-gradient(circle at 30% 25%, oklch(95% 0.04 var(--h)), oklch(84% 0.08 var(--h)));
  box-shadow: inset 0 0 0 1px oklch(70% 0.08 var(--h) / .35);
}
.bkt-marquee-who {
  display: grid; line-height: 1.25; min-width: 0;
  & b { font-weight: 600; font-size: 13.5px; }
  & small { font-size: 12px; color: var(--bkt-marquee-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

@media (hover: hover) {
  .bkt-marquee-row:has(.bkt-marquee-card:hover) .bkt-marquee-card:not(:hover) { opacity: .5; filter: saturate(.4); }
  .bkt-marquee-card:hover {
    translate: 0 -5px;
    box-shadow: 0 1px 0 color-mix(in oklch, var(--bkt-marquee-ink) 4%, transparent), 0 22px 40px -22px color-mix(in oklch, var(--bkt-marquee-ink) 45%, transparent);
  }
}

@container bkt-marquee (min-width: 860px) {
  .bkt-marquee-head {
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
    grid-template-areas: "eyebrow ctl" "title stats" "lede stats";
    align-items: end;
    row-gap: 18px;
  }
  .bkt-marquee-stats { margin-top: 0; align-self: end; }
  .bkt-marquee-row { padding-block: 14px 22px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-marquee-ctl { display: none; }
  .bkt-marquee-head { grid-template-areas: "eyebrow eyebrow" "title title" "lede lede" "stats stats"; }
  .bkt-marquee-row {
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-padding-inline: var(--bkt-marquee-gutter);
    padding-inline: var(--bkt-marquee-gutter);
    -webkit-mask-image: none; mask-image: none;
    scrollbar-width: thin;
  }
  .bkt-marquee-track { will-change: auto; }
  .bkt-marquee-card { scroll-snap-align: start; transition: none; }
  .bkt-marquee-card:hover { translate: none; }
}
@container bkt-marquee (min-width: 860px) {
  @media (prefers-reduced-motion: reduce) {
    .bkt-marquee-head { grid-template-areas: "eyebrow eyebrow" "title stats" "lede stats"; }
  }
}

