const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const ctl = root.querySelector('.bkt-marquee-ctl');
const ctlText = ctl.querySelector('span');
const SPEED = 34;          // px per second at full rate
const EASE_MS = 170;       // time constant for spin-up / spin-down

const rows = [...root.querySelectorAll('.bkt-marquee-row')].map((row, k) => ({
  row,
  track: row.querySelector('.bkt-marquee-track'),
  set: row.querySelector('.bkt-marquee-set'),
  dir: row.dataset.dir === 'right' ? -1 : 1,
  phase: k * 0.41,          // offset so the rows never line up card-for-card
  clone: null, anim: null, rate: 0, hover: false, width: 0
}));

let held = false, onScreen = false, raf = 0, last = 0;

const goal = (r) => (held || !onScreen || document.hidden || r.hover) ? 0 : 1;

// One WAAPI animation per row: translate the track by exactly one set width.
// The set carries a trailing padding equal to the gap, so the cloned copy lands
// pixel-for-pixel where the original started and the loop has no seam.
function build() {
  rows.forEach((r) => {
    if (reduce.matches) {
      if (r.anim) { r.anim.cancel(); r.anim = null; }
      if (r.clone) { r.clone.remove(); r.clone = null; }
      return;
    }
    if (!r.clone) {
      r.clone = r.set.cloneNode(true);
      r.clone.setAttribute('aria-hidden', 'true');
      r.clone.inert = true;
      r.track.append(r.clone);
    }
    const w = r.set.getBoundingClientRect().width;
    if (!w || Math.abs(w - r.width) < 1 && r.anim) return;
    let p = r.phase;
    if (r.anim) {
      const d = r.anim.effect.getTiming().duration;
      p = ((r.anim.currentTime || 0) % d) / d;
      r.anim.cancel();
    }
    r.width = w;
    const dur = (w / SPEED) * 1000;
    const kf = [{ transform: 'translate3d(0,0,0)' }, { transform: 'translate3d(' + (-w) + 'px,0,0)' }];
    r.anim = r.track.animate(r.dir > 0 ? kf : kf.reverse(), { duration: dur, iterations: Infinity });
    r.anim.currentTime = p * dur;
    if (r.rate > 0) r.anim.playbackRate = r.rate; else r.anim.pause();
  });
  kick();
}

// Instead of snapping to a stop, the playback rate eases toward its goal with an
// exponential approach, so hovering a row brakes it like a turntable.
function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(50, now - last) : 16;
  last = now;
  const k = 1 - Math.exp(-dt / EASE_MS);
  let busy = false;
  for (const r of rows) {
    if (!r.anim) continue;
    const g = goal(r);
    r.rate += (g - r.rate) * k;
    if (Math.abs(g - r.rate) < 0.004) r.rate = g; else busy = true;
    if (r.rate === 0) {
      if (r.anim.playState === 'running') r.anim.pause();
    } else {
      r.anim.playbackRate = r.rate;
      if (r.anim.playState !== 'running') r.anim.play();
    }
  }
  if (busy) raf = requestAnimationFrame(step); else last = 0;
}
function kick() { if (!raf) { last = 0; raf = requestAnimationFrame(step); } }

rows.forEach((r) => {
  r.row.addEventListener('pointerenter', (e) => { if (e.pointerType === 'mouse') { r.hover = true; kick(); } });
  r.row.addEventListener('pointerleave', () => { r.hover = false; kick(); });
});

ctl.addEventListener('click', () => {
  held = !held;
  root.classList.toggle('is-held', held);
  ctl.setAttribute('aria-label', held ? 'Play motion' : 'Pause motion');
  ctlText.textContent = held ? 'Play' : 'Pause';
  kick();
});

const io = new IntersectionObserver((es) => { onScreen = es[es.length - 1].isIntersecting; kick(); });
io.observe(root);

let lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
  const w = root.clientWidth;
  if (Math.abs(w - lastW) < 1) return;
  lastW = w;
  build();
});
ro.observe(root);

const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (document.hidden) rows.forEach((r) => { r.rate = 0; if (r.anim) r.anim.pause(); });
  kick();
};
document.addEventListener('visibilitychange', onVis);

const onReduce = () => {
  if (!root.isConnected) { reduce.removeEventListener('change', onReduce); return; }
  rows.forEach((r) => { r.width = 0; });
  build();
};
reduce.addEventListener('change', onReduce);

