.bkt-wall {
  --bkt-wall-paper: oklch(96.4% 0.016 86);
  --bkt-wall-ink: oklch(20% 0.014 55);
  --bkt-wall-accent: oklch(57% 0.19 33);
  --bkt-wall-sheet: oklch(98.8% 0.008 86);
  --bkt-wall-muted: color-mix(in oklch, var(--bkt-wall-ink) 62%, var(--bkt-wall-paper));
  --bkt-wall-rule: color-mix(in oklch, var(--bkt-wall-ink) 16%, transparent);
  --bkt-wall-hair: color-mix(in oklch, var(--bkt-wall-ink) 9%, transparent);
  --bkt-wall-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkt-wall-gap: 18px;
  --bkt-wall-cap: 560px;
  --bkt-wall-out: cubic-bezier(.2, .85, .25, 1);
  container-type: inline-size;
  container-name: bkt-wall;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(120% 60% at 100% 0%, color-mix(in oklch, var(--bkt-wall-accent) 6%, transparent), transparent 60%),
    var(--bkt-wall-paper);
  color: var(--bkt-wall-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, figure, blockquote, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
}

.bkt-wall-in { padding: clamp(32px, 5.5cqi, 72px) clamp(16px, 5cqi, 64px) clamp(28px, 4.5cqi, 56px); }

.bkt-wall-head {
  display: grid;
  gap: 16px 48px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "kicker" "title" "lede" "bar";
  padding-bottom: 26px;
}
.bkt-wall-kicker {
  grid-area: kicker;
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  border-top: 3px double var(--bkt-wall-ink);
  padding-top: 10px;
  font-size: 11px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase;
  & > span:first-child { color: var(--bkt-wall-accent); }
}
.bkt-wall-mast {
  display: inline-flex; align-items: center; gap: 6px; color: var(--bkt-wall-muted);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
}
.bkt-wall-title {
  grid-area: title;
  font-family: var(--bkt-wall-serif);
  font-weight: 600;
  font-size: clamp(32px, 4.6cqi + 14px, 64px);
  line-height: 1;
  letter-spacing: -.025em;
  text-wrap: balance;
  max-width: 15ch;
}
.bkt-wall-lede { grid-area: lede; max-width: 50ch; color: var(--bkt-wall-muted); font-size: clamp(15px, .5cqi + 12.5px, 17px); text-wrap: pretty; }

.bkt-wall-bar {
  grid-area: bar;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 24px;
  border-top: 1px solid var(--bkt-wall-rule);
  padding-top: 16px;
}
.bkt-wall-filter {
  display: flex; flex-wrap: wrap; gap: 6px;
  & legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.bkt-wall-chip {
  position: relative;
  display: inline-flex; align-items: baseline; gap: 6px;
  padding: 7px 12px 7px 13px;
  border: 1px solid var(--bkt-wall-rule);
  border-radius: 999px;
  font-size: 13.5px; font-weight: 520;
  cursor: pointer;
  user-select: none;
  transition: background-color .25s var(--bkt-wall-out), color .25s var(--bkt-wall-out), border-color .25s;
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & small { font-size: 11px; font-variant-numeric: tabular-nums; color: var(--bkt-wall-muted); transition: color .25s; }
  &:hover { border-color: color-mix(in oklch, var(--bkt-wall-ink) 40%, transparent); }
  &:has(input:checked) { background: var(--bkt-wall-ink); color: var(--bkt-wall-paper); border-color: var(--bkt-wall-ink); }
  &:has(input:checked) small { color: color-mix(in oklch, var(--bkt-wall-paper) 70%, transparent); }
  &:has(input:focus-visible) { outline: 2px solid var(--bkt-wall-accent); outline-offset: 2px; }
}
.bkt-wall-status { font-size: 13px; color: var(--bkt-wall-muted); font-variant-numeric: tabular-nums; & b { color: var(--bkt-wall-ink); font-weight: 650; } }

.bkt-wall-clip {
  position: relative;
  max-height: var(--bkt-wall-cap);
  overflow: hidden;
  margin-inline: -6px;
  padding-inline: 6px;
  &::after {
    content: "";
    position: absolute; inset: auto 0 0 0; height: 160px;
    background: linear-gradient(to bottom, color-mix(in oklch, var(--bkt-wall-paper) 0%, transparent), var(--bkt-wall-paper) 88%);
    pointer-events: none;
    transition: opacity .4s var(--bkt-wall-out);
  }
}
.bkt-wall.is-open .bkt-wall-clip { max-height: none; }
.bkt-wall:is(.is-open, .is-fits) .bkt-wall-clip::after { opacity: 0; }
.bkt-wall.is-fits .bkt-wall-foot { display: none; }

.bkt-wall-grid {
  list-style: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-rows: 4px;
  column-gap: var(--bkt-wall-gap);
  align-items: start;
  padding-top: 6px;
}
.bkt-wall-card {
  grid-row-end: span var(--span, 52);
  position: relative;
  background: var(--bkt-wall-sheet);
  border: 1px solid var(--bkt-wall-hair);
  border-radius: 3px;
  box-shadow: 0 1px 0 var(--bkt-wall-hair), 0 14px 30px -26px color-mix(in oklch, var(--bkt-wall-ink) 60%, transparent);
  &[hidden] { display: none; }
  &::before {
    content: ""; position: absolute; left: -1px; top: -1px; bottom: -1px; width: 3px;
    background: var(--bkt-wall-accent);
    transform: scaleY(0); transform-origin: 50% 0;
    transition: transform .5s var(--bkt-wall-out);
  }
  &:hover::before { transform: scaleY(1); }
  & figure { display: grid; gap: 14px; padding: 20px 22px 20px; }
  & blockquote { font-family: var(--bkt-wall-serif); font-size: 17px; line-height: 1.45; text-wrap: pretty; letter-spacing: -.003em; }
  & figcaption { display: grid; gap: 1px; font-size: 13px; line-height: 1.35; padding-top: 12px; border-top: 1px solid var(--bkt-wall-hair); }
  & figcaption b { font-weight: 650; font-size: 13.5px; }
  & figcaption span { color: var(--bkt-wall-muted); }
  & figcaption i { font-family: var(--bkt-wall-serif); font-size: 1.05em; }
}
.bkt-wall-role { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--bkt-wall-accent); }
.bkt-wall-orn { width: 34px; height: 26px; fill: var(--bkt-wall-accent); margin-top: -2px; }
.bkt-wall-card.is-lead {
  border-top: 3px solid var(--bkt-wall-ink);
  & blockquote { font-size: clamp(20px, 1.1cqi + 14px, 25px); line-height: 1.28; letter-spacing: -.012em; font-weight: 500; }
}
.bkt-wall-stat {
  display: grid; gap: 2px;
  padding-bottom: 12px; border-bottom: 1px solid var(--bkt-wall-hair);
  & b { font-family: var(--bkt-wall-serif); font-weight: 600; font-size: clamp(46px, 3cqi + 30px, 64px); line-height: .95; letter-spacing: -.04em; font-variant-numeric: tabular-nums lining-nums; }
  & small { font-size: .38em; letter-spacing: 0; margin-left: 4px; color: var(--bkt-wall-accent); }
  & span { font-size: 12.5px; color: var(--bkt-wall-muted); }
}

.bkt-wall-foot { display: flex; justify-content: center; margin-top: 18px; position: relative; z-index: 1; }
.bkt-wall-more {
  display: inline-flex; align-items: center; gap: 8px;
  font: inherit; font-size: 14px; font-weight: 600;
  color: var(--bkt-wall-paper);
  background: var(--bkt-wall-ink);
  border: 0; border-radius: 999px;
  padding: 11px 18px 11px 20px;
  cursor: pointer;
  transition: background-color .25s, translate .3s var(--bkt-wall-out);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s var(--bkt-wall-out); }
  &:hover { background: color-mix(in oklch, var(--bkt-wall-ink) 82%, var(--bkt-wall-accent)); translate: 0 -1px; }
  &:focus-visible { outline: 2px solid var(--bkt-wall-accent); outline-offset: 3px; }
  &[aria-expanded="true"] svg { rotate: 180deg; }
}

@container bkt-wall (min-width: 560px) {
  .bkt-wall { --bkt-wall-cap: 600px; }
