const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const grid = root.querySelector('.bkt-wall-grid');
const clip = root.querySelector('.bkt-wall-clip');
const more = root.querySelector('.bkt-wall-more');
const moreText = more.querySelector('span');
const status = root.querySelector('.bkt-wall-status');
const cards = [...grid.children];
const ROW = 4;
const SPRING = CSS.supports('transition-timing-function', 'linear(0, 1)')
  ? 'linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1)'
  : 'cubic-bezier(.2, .9, .3, 1.15)';
const OUT = 'cubic-bezier(.2, .85, .25, 1)';

// radio groups are document-wide, so every mounted copy gets its own name
const group = 'bkt-wall-' + Math.random().toString(36).slice(2, 9);
root.querySelectorAll('.bkt-wall-filter input').forEach((i) => { i.name = group; });

// Masonry without masonry: 4px implicit rows, each card spans ceil((h + gap) / 4).
// Cards are align-self:start, so their measured height never depends on the span.
const gapPx = () => parseFloat(getComputedStyle(grid).columnGap) || 18;
function span(c) {
  const h = c.offsetHeight;
  if (h) c.style.setProperty('--span', Math.ceil((h + gapPx()) / ROW));
}
function fit() {
  const cap = parseFloat(getComputedStyle(root).getPropertyValue('--bkt-wall-cap')) || 600;
  root.classList.toggle('is-fits', grid.offsetHeight <= cap + 60);
}
const ro = new ResizeObserver((entries) => {
  if (!root.isConnected) { ro.disconnect(); return; }
  for (const e of entries) span(e.target);
  fit();
});
cards.forEach((c) => ro.observe(c));

let ticket = 0;
function apply(role) {
  const t = ++ticket;
  const show = (c) => role === 'all' || c.dataset.role === role;
  const before = new Map();
  cards.forEach((c) => { if (!c.hidden) before.set(c, c.getBoundingClientRect()); });
  const leaving = cards.filter((c) => !c.hidden && !show(c));

  const commit = () => {
    if (t !== ticket || !root.isConnected) return;
    cards.forEach((c) => { c.getAnimations().forEach((a) => a.cancel()); c.hidden = !show(c); });
    cards.forEach((c) => { if (!c.hidden) span(c); });
    const shown = cards.filter((c) => !c.hidden);
    status.innerHTML = 'Showing <b>' + shown.length + '</b> of ' + cards.length + ' letters';
    moreText.textContent = root.classList.contains('is-open') ? 'Fold the wall' : 'Read all ' + shown.length + ' letters';
    fit();
    if (reduce.matches) return;
    // FLIP: Last is now laid out; invert from First and play to identity.
    let n = 0;
    shown.forEach((c) => {
      const a = c.getBoundingClientRect(), b = before.get(c);
      if (b) {
        const dx = b.left - a.left, dy = b.top - a.top;
        if (Math.abs(dx) + Math.abs(dy) > 0.5) {
          c.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 640, easing: SPRING });
        }
      } else {
        c.animate(
          [{ opacity: 0, transform: 'translateY(16px) scale(.97)', filter: 'blur(4px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
          { duration: 480, delay: 90 + n++ * 45, easing: OUT, fill: 'backwards' }
        );
      }
    });
  };

  if (reduce.matches || !leaving.length) { commit(); return; }
  Promise.all(leaving.map((c) => c.animate(
    [{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'scale(.96)' }],
    { duration: 170, easing: 'cubic-bezier(.4, 0, 1, 1)', fill: 'forwards' }
  ).finished)).then(commit, commit);
}

root.addEventListener('change', (e) => {
  if (e.target.name === group) apply(e.target.value);
});

more.addEventListener('click', () => {
  const open = !root.classList.contains('is-open');
  const from = clip.offsetHeight;
  root.classList.toggle('is-open', open);
  const to = clip.offsetHeight;
  more.setAttribute('aria-expanded', String(open));
  const shown = cards.filter((c) => !c.hidden).length;
  moreText.textContent = open ? 'Fold the wall' : 'Read all ' + shown + ' letters';
  if (!reduce.matches && from !== to) {
    clip.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: 620, easing: OUT });
  }
});

