@property --bkt-feature-p { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.bkt-feature {
  --bkt-feature-bg: oklch(17% 0.014 58);
  --bkt-feature-ivory: oklch(94% 0.022 85);
  --bkt-feature-brass: oklch(78% 0.105 78);
  --bkt-feature-dur: 8s;
  --bkt-feature-muted: color-mix(in oklch, var(--bkt-feature-ivory) 58%, var(--bkt-feature-bg));
  --bkt-feature-line: color-mix(in oklch, var(--bkt-feature-brass) 22%, transparent);
  --bkt-feature-faint: color-mix(in oklch, var(--bkt-feature-ivory) 8%, transparent);
  --bkt-feature-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkt-feature-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  container-name: bkt-feature;
  box-sizing: border-box;
  width: 100%;
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(70% 90% at 12% 0%, color-mix(in oklch, var(--bkt-feature-brass) 13%, transparent), transparent 62%),
    radial-gradient(60% 70% at 100% 100%, color-mix(in oklch, oklch(45% 0.09 35) 22%, transparent), transparent 70%),
    var(--bkt-feature-bg);
  color: var(--bkt-feature-ivory);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, blockquote) { margin: 0; padding: 0; }
  &::before {
    content: "";
    position: absolute; inset: clamp(8px, 1.4cqi, 16px);
    border: 1px solid var(--bkt-feature-line);
    pointer-events: none;
    z-index: -1;
  }
}

.bkt-feature-in {
  display: grid;
  gap: 28px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "stage" "list";
  padding: clamp(40px, 7cqi, 96px) clamp(26px, 6cqi, 88px);
}

.bkt-feature-head { grid-area: head; display: grid; gap: 12px; }
.bkt-feature-brand {
  display: flex; align-items: center; gap: 9px;
  font-size: 11.5px; font-weight: 600; letter-spacing: .22em; text-transform: uppercase;
  color: var(--bkt-feature-brass);
  & span { color: var(--bkt-feature-muted); letter-spacing: .16em; }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; }
}
.bkt-feature-title {
  font-weight: 300;
  font-size: clamp(22px, 1.6cqi + 15px, 32px);
  line-height: 1.15;
  letter-spacing: -.02em;
  text-wrap: balance;
  max-width: 26ch;
}
.bkt-feature-rating {
  display: flex; align-items: baseline; gap: 10px;
  font-size: 13px; color: var(--bkt-feature-muted);
  & b { font-family: var(--bkt-feature-serif); font-weight: 400; font-size: 22px; color: var(--bkt-feature-brass); font-variant-numeric: tabular-nums; }
}

.bkt-feature-stage { grid-area: stage; display: grid; gap: 28px; min-width: 0; }
.bkt-feature-deck { display: grid; }
.bkt-feature-deck > * { grid-area: 1 / 1; min-width: 0; display: grid; gap: 22px; align-content: start; }
.bkt-feature-ghost { visibility: hidden; pointer-events: none; }

.bkt-feature-mark { width: clamp(38px, 3cqi + 22px, 56px); height: auto; fill: var(--bkt-feature-brass); opacity: .9; }
.bkt-feature-q {
  font-family: var(--bkt-feature-serif);
  font-size: clamp(23px, 2.1cqi + 14px, 40px);
  line-height: 1.24;
  letter-spacing: -.012em;
  text-wrap: pretty;
  & em { font-style: italic; color: var(--bkt-feature-brass); }
}
.bkt-feature-by {
  display: grid; gap: 18px;
  padding-top: 20px;
  border-top: 1px solid var(--bkt-feature-line);
}
.bkt-feature-who {
  display: grid; gap: 4px;
  & b { font-weight: 600; font-size: 12px; letter-spacing: .2em; text-transform: uppercase; }
  & span { font-size: 14px; color: var(--bkt-feature-muted); }
}
.bkt-feature-stat {
  display: flex; align-items: baseline; gap: 12px;
  & b { font-weight: 250; font-size: clamp(32px, 2cqi + 22px, 46px); line-height: 1; letter-spacing: -.03em; color: var(--bkt-feature-brass); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & span { font-size: 13px; color: var(--bkt-feature-muted); max-width: 22ch; line-height: 1.35; }
}

/* entry choreography: every node inserted by a slide change starts from here */
.bkt-feature-live {
  & .bkt-feature-mark { transition: opacity .6s var(--bkt-feature-out), scale .8s var(--bkt-feature-out); @starting-style { opacity: 0; scale: .7; } }
  & .bkt-feature-w {
    display: inline-block;
    transition: opacity .7s var(--bkt-feature-out), filter .7s var(--bkt-feature-out), translate .9s var(--bkt-feature-out);
    transition-delay: calc(var(--i) * 17ms + 60ms);
    @starting-style { opacity: 0; filter: blur(8px); translate: 0 .38em; }
  }
  & .bkt-feature-who, & .bkt-feature-stat {
    transition: opacity .6s var(--bkt-feature-out), translate .7s var(--bkt-feature-out);
    transition-delay: calc(var(--d, 0) * 1ms);
    @starting-style { opacity: 0; translate: 0 10px; }
  }
}

.bkt-feature-ctl { display: flex; align-items: center; gap: 10px; }
.bkt-feature-btn {
  width: 42px; height: 42px; flex: none;
  display: grid; place-items: center;
  border-radius: 50%;
  border: 1px solid var(--bkt-feature-line);
  background: transparent;
  color: var(--bkt-feature-ivory);
  cursor: pointer;
  transition: background-color .3s, border-color .3s, color .3s, scale .3s var(--bkt-feature-out);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: var(--bkt-feature-brass); border-color: var(--bkt-feature-brass); color: var(--bkt-feature-bg); }
  &:active { scale: .94; }
  &:focus-visible { outline: 1.5px solid var(--bkt-feature-brass); outline-offset: 3px; }
}
.bkt-feature-hold { margin-left: auto; }
.bkt-feature-i-play { display: none; fill: currentColor; stroke: none; }
.bkt-feature.is-held {
  & .bkt-feature-i-pause { display: none; }
  & .bkt-feature-i-play { display: inline; }
}
.bkt-feature-count {
  min-width: 64px; text-align: center;
  font-size: 13px; letter-spacing: .12em; color: var(--bkt-feature-muted);
  font-variant-numeric: tabular-nums;
  & b { color: var(--bkt-feature-ivory); font-weight: 500; }
  & span { margin-inline: 6px; color: var(--bkt-feature-line); }
}

.bkt-feature-list {
  grid-area: list;
  display: flex; gap: 6px; flex-wrap: wrap;
}
.bkt-feature-tab {
  display: flex; align-items: center; gap: 14px;
  font: inherit; color: inherit; text-align: left;
  background: transparent; border: 0; padding: 4px; border-radius: 999px;
  cursor: pointer;
  &:focus-visible { outline: 1.5px solid var(--bkt-feature-brass); outline-offset: 2px; }
}
.bkt-feature-tname {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap;
  & b { display: block; font-weight: 500; font-size: 14.5px; letter-spacing: -.005em; }
  & small { display: block; font-size: 12.5px; color: var(--bkt-feature-muted); }
}
.bkt-feature-ring {
  --bkt-feature-p: 0%;
  position: relative; flex: none;
  width: 48px; height: 48px; border-radius: 50%;
  padding: 2px;
  background: conic-gradient(var(--bkt-feature-brass) var(--bkt-feature-p), var(--bkt-feature-faint) 0);
  transition: scale .5s var(--bkt-feature-out);
}
.bkt-feature-av {
  display: grid; place-items: center;
  width: 100%; height: 100%; border-radius: 50%;
  border: 2px solid var(--bkt-feature-bg);
  font-family: var(--bkt-feature-serif); font-style: italic; font-size: 17px;
  color: oklch(90% 0.05 var(--h));
  background: radial-gradient(circle at 30% 25%, oklch(42% 0.07 var(--h)), oklch(24% 0.04 var(--h)));
  filter: saturate(.5) brightness(.8);
  transition: filter .5s var(--bkt-feature-out);
}
.bkt-feature-tab:hover .bkt-feature-av { filter: saturate(.85) brightness(.95); }
.bkt-feature-tab[aria-selected="true"] {
  & .bkt-feature-av { filter: none; }
  & .bkt-feature-ring { animation: bkt-feature-fill var(--bkt-feature-dur) linear forwards; }
}
.bkt-feature:is(.is-held, .is-off) .bkt-feature-tab[aria-selected="true"] .bkt-feature-ring,
.bkt-feature:has(.bkt-feature-deck:hover, .bkt-feature-list:hover, :focus-visible) .bkt-feature-tab[aria-selected="true"] .bkt-feature-ring { animation-play-state: paused; }

@keyframes bkt-feature-fill { from { --bkt-feature-p: 0%; } to { --bkt-feature-p: 100%; } }

@container bkt-feature (min-width: 900px) {
  .bkt-feature-in {
    grid-template-columns: minmax(0, 1fr) minmax(250px, 290px);
    grid-template-areas: "head head" "stage list";
    column-gap: clamp(40px, 6cqi, 88px);
    row-gap: 44px;
  }
  .bkt-feature-head { grid-template-columns: minmax(0, 1fr) auto; align-items: end; column-gap: 40px; }
  .bkt-feature-brand { grid-column: 1 / -1; }
  .bkt-feature-rating { flex-direction: column; align-items: flex-end; gap: 0; text-align: right; & b { font-size: 34px; line-height: 1; } }
  .bkt-feature-by { grid-template-columns: minmax(0, 1fr) auto; align-items: end; column-gap: 32px; }
  .bkt-feature-stat { flex-direction: column; align-items: flex-end; gap: 6px; text-align: right; }
  .bkt-feature-list {
    flex-direction: column; flex-wrap: nowrap; gap: 4px;
    align-self: start;
    padding-left: 28px;
    border-left: 1px solid var(--bkt-feature-line);
  }
  .bkt-feature-tab {
    width: 100%; border-radius: 16px; padding: 10px 12px 10px 10px;
    transition: background-color .4s var(--bkt-feature-out);
    &:hover { background: var(--bkt-feature-faint); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--bkt-feature-brass) 10%, transparent); }
  }
  .bkt-feature-tname { position: static; width: auto; height: auto; overflow: visible; clip-path: none; white-space: normal; min-width: 0; }
  .bkt-feature-ring { width: 46px; height: 46px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-feature-tab[aria-selected="true"] .bkt-feature-ring { animation: none; --bkt-feature-p: 100%; }
  .bkt-feature-hold { display: none; }
  .bkt-feature-live {
    & .bkt-feature-mark, & .bkt-feature-w, & .bkt-feature-who, & .bkt-feature-stat {
      transition: opacity .25s linear; transition-delay: 0ms;
      @starting-style { opacity: 0; filter: none; translate: none; scale: none; }
    }
  }
  .bkt-feature-btn, .bkt-feature-av, .bkt-feature-tab { transition: none; }
}

