const DATA = [{"n": "Isabella Marchetti", "r": "Owner", "p": "Villa Celandine", "c": "Lake Como", "q": "Hearthkeep let us stop *renting our guests* from the booking sites. Two seasons in, a third of our stays come to us direct — and those guests arrive already knowing our names.", "s": "34%", "sl": "of stays booked direct, up from 19%"}, {"n": "Laurent Aubert", "r": "General manager", "p": "Hôtel Saint-Aubert", "c": "Lyon", "q": "Housekeeping, the front desk and the kitchen finally read from the same page. When a guest mentions an allergy at check-in, *the pastry chef knows* before they reach the lift.", "s": "−58%", "sl": "average check-in, from 26 minutes to 11"}, {"n": "Nadia Okonjo-Brook", "r": "Founder", "p": "The Saltings", "c": "Norfolk coast", "q": "I am the owner, the night porter and, now and then, the plumber. Hearthkeep is the first system that *behaves like it knows that.*", "s": "6 hrs", "sl": "of admin handed back every week"}, {"n": "Kenji Morimoto", "r": "Director", "p": "Ryokan Kōyō", "c": "Hakone", "q": "Our guests come for the silence. Hearthkeep handles the noise — deposits, channel calendars, late arrivals — *without asking us to change how we host.*", "s": "4.96", "sl": "average guest rating across 1,240 stays"}, {"n": "Sofía Calderón", "r": "Managing partner", "p": "Casa Albar", "c": "Mallorca", "q": "We run three houses on one island with one team. The rate engine took our shoulder-season occupancy from 54% to 78% *without a single discount code.*", "s": "+24 pts", "sl": "shoulder-season occupancy, 54% to 78%"}];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const live = root.querySelector('.bkt-feature-live');
const tabs = [...root.querySelectorAll('.bkt-feature-tab')];
const countEl = root.querySelector('.bkt-feature-count b');
const hold = root.querySelector('.bkt-feature-hold');
const mark = live.querySelector('.bkt-feature-mark').outerHTML;

// ids must be unique per mounted copy
const uid = Math.random().toString(36).slice(2, 8);
live.id = 'bkt-feature-panel-' + uid;
tabs.forEach((t, i) => { t.id = 'bkt-feature-tab-' + uid + '-' + i; t.setAttribute('aria-controls', live.id); });
live.setAttribute('aria-labelledby', tabs[0].id);

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
// One span per word, *emphasis* kept, each carrying --i for the stagger.
function words(q) {
  let em = false;
  return q.split(' ').map((w, i) => {
    const open = w.startsWith('*'), close = w.endsWith('*');
    if (open) em = true;
    const html = '<span class="bkt-feature-w" style="--i:' + i + '">' + esc(w.replace(/\*/g, '')) + '</span>';
    const out = em ? '<em>' + html + '</em>' : html;
    if (close) em = false;
    return out;
  }).join(' ');
}
function render(i) {
  const d = DATA[i];
  const n = d.q.split(' ').length;
  live.innerHTML = mark +
    '<blockquote class="bkt-feature-q"><p>' + words(d.q) + '</p></blockquote>' +
    '<div class="bkt-feature-by">' +
      '<p class="bkt-feature-who" style="--d:' + (180 + n * 17) + '"><b>' + esc(d.n) + '</b><span>' + esc(d.r) + ' · ' + esc(d.p) + ', ' + esc(d.c) + '</span></p>' +
      '<p class="bkt-feature-stat" style="--d:' + (300 + n * 17) + '"><b>' + esc(d.s) + '</b><span>' + esc(d.sl) + '</span></p>' +
    '</div>';
}

let cur = 0, tok = 0, held = false;
function go(i, user) {
  i = (i + DATA.length) % DATA.length;
  const same = i === cur;
  cur = i;
  tabs.forEach((t, k) => {
    const on = k === i;
    t.setAttribute('aria-selected', String(on));
    t.tabIndex = on ? 0 : -1;
  });
  countEl.textContent = String(i + 1).padStart(2, '0');
  live.setAttribute('aria-labelledby', tabs[i].id);
  live.setAttribute('aria-live', user || held ? 'polite' : 'off');
  if (same && user) return;
  const t = ++tok;
  if (reduce.matches) { render(i); return; }
  const out = live.animate(
    [{ opacity: 1, transform: 'none', filter: 'blur(0)' }, { opacity: 0, transform: 'translateY(-8px)', filter: 'blur(5px)' }],
    { duration: 240, easing: 'cubic-bezier(.5, 0, .75, 0)', fill: 'forwards' }
  );
  out.finished.then(() => { if (t === tok) render(i); out.cancel(); }, () => {});
}

// Autoplay is the ring itself: when the active ring's @property sweep ends, advance.
root.addEventListener('animationend', (e) => {
  if (e.animationName === 'bkt-feature-fill' && !held) go(cur + 1, false);
});

root.querySelector('.bkt-feature-list').addEventListener('click', (e) => {
  const t = e.target.closest('.bkt-feature-tab');
  if (t) go(tabs.indexOf(t), true);
});
root.querySelector('.bkt-feature-list').addEventListener('keydown', (e) => {
  const map = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
  let n = null;
  if (e.key in map) n = cur + map[e.key];
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = DATA.length - 1;
  if (n === null) return;
  e.preventDefault();
  go(n, true);
  tabs[cur].focus();
});
root.querySelectorAll('[data-step]').forEach((b) => b.addEventListener('click', () => go(cur + Number(b.dataset.step), true)));

hold.addEventListener('click', () => {
  held = !held;
  root.classList.toggle('is-held', held);
  hold.setAttribute('aria-label', held ? 'Resume autoplay' : 'Pause autoplay');
  live.setAttribute('aria-live', held ? 'polite' : 'off');
  if (!held) {
    // restart the sweep for the current host so resuming never skips instantly
    const ring = tabs[cur].querySelector('.bkt-feature-ring');
    ring.getAnimations().forEach((a) => { a.currentTime = 0; });
  }
});

let seen = false, onScreen = false;
const sync = () => root.classList.toggle('is-off', !onScreen || document.hidden);
const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  sync();
  if (onScreen && !seen) { seen = true; if (!reduce.matches) render(cur); }
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); io.disconnect(); return; }
  sync();
};
document.addEventListener('visibilitychange', onVis);

css:
.bkt-video {
  --bkt-video-bg: oklch(16.5% 0.012 45);
  --bkt-video-text: oklch(95% 0.014 80);
  --bkt-video-accent: oklch(68% 0.19 32);
  --bkt-video-muted: color-mix(in oklch, var(--bkt-video-text) 56%, var(--bkt-video-bg));
  --bkt-video-line: color-mix(in oklch, var(--bkt-video-text) 12%, transparent);
  --bkt-video-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkt-video-out: cubic-bezier(.19, 1, .22, 1);
  --bkt-video-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  container-type: inline-size;
  container-name: bkt-video;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(80% 60% at 50% 0%, color-mix(in oklch, var(--bkt-video-accent) 10%, transparent), transparent 70%),
    var(--bkt-video-bg);
  color: var(--bkt-video-text);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p) { margin: 0; }
}
.bkt-video-in { padding-block: clamp(40px, 7cqi, 88px); display: grid; gap: clamp(26px, 4cqi, 44px); }
.bkt-video-head {
  padding-inline: clamp(16px, 5cqi, 64px);
  display: grid; gap: 12px;
  grid-template-areas: "kicker" "title" "lede";
}
.bkt-video-kicker {
  grid-area: kicker;
  display: flex; align-items: center; gap: 8px;
  font-family: var(--bkt-video-mono); font-size: 11.5px; letter-spacing: .14em; text-transform: uppercase;
  color: var(--bkt-video-accent);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
}
.bkt-video-title { grid-area: title; font-size: clamp(28px, 3.6cqi + 14px, 52px); font-weight: 700; letter-spacing: -.035em; line-height: 1.02; text-wrap: balance; max-width: 18ch; }
.bkt-video-lede { grid-area: lede; color: var(--bkt-video-muted); max-width: 52ch; text-wrap: pretty; font-size: clamp(14.5px, .5cqi + 12px, 16.5px); }

.bkt-video-track {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: min(82%, 340px);
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: clamp(16px, 5cqi, 64px);
  padding: 4px clamp(16px, 5cqi, 64px) 16px;
  scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
}
.bkt-video-card {
  scroll-snap-align: start;
  display: grid; gap: 14px; align-content: start;
  min-width: 0;
  transition: opacity .5s var(--bkt-video-out), filter .5s var(--bkt-video-out);
}
.bkt-video:has(.bkt-video-card.is-playing) .bkt-video-card:not(.is-playing) { opacity: .42; filter: saturate(.3); }

.bkt-video-frame {
  position: relative;
  cursor: pointer;
  aspect-ratio: 4 / 5;
  border-radius: 14px;
  overflow: hidden;
  isolation: isolate;
  background: oklch(20% 0.03 var(--h));
  box-shadow: 0 0 0 1px var(--bkt-video-line), 0 30px 60px -36px oklch(0% 0 0 / .9);
  transition: box-shadow .5s var(--bkt-video-out);
}
.bkt-video-card.is-playing .bkt-video-frame { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--bkt-video-accent) 70%, transparent), 0 30px 70px -30px color-mix(in oklch, var(--bkt-video-accent) 45%, transparent); }

/* the "footage": gradient set + window + practical lamp + silhouette with a rim light */
.bkt-video-scene {
  position: absolute; inset: 0; z-index: -1;
  background:
    radial-gradient(60% 45% at 78% 22%, oklch(72% 0.13 calc(var(--h) + 20) / .55), transparent 70%),
    radial-gradient(90% 70% at 20% 100%, oklch(34% 0.08 var(--h)), transparent 70%),
    linear-gradient(160deg, oklch(34% 0.06 var(--h)), oklch(17% 0.035 var(--h)));
  transform-origin: 60% 40%;
  &::after {
    content: ""; position: absolute; inset: 0;
    background: radial-gradient(120% 90% at 50% 45%, transparent 55%, oklch(8% 0.02 var(--h) / .85));
  }
}
.bkt-video-win {
  position: absolute; right: 9%; top: 9%; width: 34%; height: 38%;
  background: repeating-linear-gradient(180deg, oklch(86% 0.08 calc(var(--h) + 25) / .55) 0 7px, transparent 7px 13px);
  filter: blur(1.2px);
  clip-path: polygon(8% 0, 100% 4%, 92% 100%, 0 96%);
  opacity: .8;
}
.bkt-video-lamp {
  position: absolute; right: 30%; top: 52%; width: 15%; aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, oklch(92% 0.09 80 / .95), oklch(80% 0.14 60 / .25) 45%, transparent 70%);
  filter: blur(2px);
}
.bkt-video-fig { position: absolute; inset: 0; width: 100%; height: 100%; }
.bkt-video-sil { fill: oklch(13% 0.02 var(--h)); }
.bkt-video-rim { fill: oklch(78% 0.09 calc(var(--h) + 20)); opacity: .75; }
.bkt-video-face { transform-box: fill-box; transform-origin: 50% 100%; }

.bkt-video-lb {
  position: absolute; inset: 0; pointer-events: none;
  &::before, &::after {
    content: ""; position: absolute; left: 0; right: 0; height: 8%;
    background: oklch(6% 0.01 var(--h));
    transform: scaleY(0);
    transition: transform .6s var(--bkt-video-out);
  }
  &::before { top: 0; transform-origin: 50% 0; }
  &::after { bottom: 0; transform-origin: 50% 100%; }
}
.bkt-video-card.is-playing .bkt-video-lb::before, .bkt-video-card.is-playing .bkt-video-lb::after { transform: scaleY(1); }

.bkt-video-top {
  position: absolute; top: 12px; left: 12px; right: 12px;
  display: flex; align-items: center; gap: 8px;
  font-family: var(--bkt-video-mono); font-size: 11px; letter-spacing: .06em;
}
.bkt-video-tag { padding: 4px 8px; border-radius: 6px; background: oklch(10% 0.01 var(--h) / .55); backdrop-filter: blur(6px); text-transform: uppercase; letter-spacing: .1em; font-size: 10px; }
.bkt-video-dur { margin-left: auto; padding: 4px 7px; border-radius: 6px; background: oklch(10% 0.01 var(--h) / .55); font-variant-numeric: tabular-nums; }
.bkt-video-eq {
  display: none; align-items: end; gap: 2px; height: 14px; margin-left: auto;
  & i { width: 3px; height: 100%; border-radius: 1px; background: var(--bkt-video-accent); transform-origin: 50% 100%; transform: scaleY(.25); animation: bkt-video-eq .9s cubic-bezier(.45, 0, .55, 1) calc(var(--i) * -230ms) infinite alternate; animation-play-state: paused; }
}
.bkt-video-card.is-playing .bkt-video-eq { display: flex; }
.bkt-video-card.is-playing .bkt-video-eq ~ .bkt-video-dur { margin-left: 0; }
.bkt-video-card.is-playing:not(.is-stalled) .bkt-video-eq i { animation-play-state: running; }
@keyframes bkt-video-eq { 0% { transform: scaleY(.2); } 40% { transform: scaleY(.9); } 70% { transform: scaleY(.45); } 100% { transform: scaleY(1); } }

.bkt-video-play {
  position: absolute; left: var(--px, 50%); top: 44%;
  width: 68px; height: 68px; margin: -34px 0 0 -34px;
  border-radius: 50%; border: 0; padding: 0;
  background: var(--bkt-video-accent);
  color: oklch(14% 0.02 30);
  cursor: pointer;
  box-shadow: 0 0 0 0 color-mix(in oklch, var(--bkt-video-accent) 50%, transparent), 0 14px 30px -10px oklch(0% 0 0 / .7);
  transition: scale .5s var(--bkt-video-spring), opacity .4s var(--bkt-video-out), translate .5s var(--bkt-video-out), box-shadow .4s var(--bkt-video-out), width .5s var(--bkt-video-out), height .5s var(--bkt-video-out), margin .5s var(--bkt-video-out);
  &:hover { scale: 1.08; box-shadow: 0 0 0 10px color-mix(in oklch, var(--bkt-video-accent) 22%, transparent), 0 14px 30px -10px oklch(0% 0 0 / .7); }
  &:active { scale: .95; }
  &:focus-visible { outline: 2px solid var(--bkt-video-text); outline-offset: 4px; }
  & span {
    position: absolute; left: 36%; top: 32%; width: 34%; height: 36%;
    background: currentColor;
    transition: clip-path .38s var(--bkt-video-out), left .38s var(--bkt-video-out);
  }
  /* two halves of a play triangle that morph into two pause bars */
  & .bkt-video-pl { clip-path: polygon(0 0, 50% 25%, 50% 75%, 0 100%); }
  & .bkt-video-pr { clip-path: polygon(50% 25%, 100% 50%, 100% 50%, 50% 75%); }
}
.bkt-video-card.is-playing .bkt-video-play {
  width: 44px; height: 44px; margin: -22px 0 0 -22px;
  opacity: 0;
  & span { left: 33%; }
  & .bkt-video-pl { clip-path: polygon(0 0, 36% 0, 36% 100%, 0 100%); }
  & .bkt-video-pr { clip-path: polygon(64% 0, 100% 0, 100% 100%, 64% 100%); }
}
.bkt-video-card.is-playing:is(:hover, :focus-within) .bkt-video-play { opacity: 1; }

.bkt-video-cc {
  position: absolute; left: 12px; right: 12px; bottom: 54px;
  text-align: center;
  font-size: clamp(13px, .5cqi + 11px, 15px); line-height: 1.35; font-weight: 520;
  text-wrap: balance;
  opacity: 0; translate: 0 6px;
  transition: opacity .35s var(--bkt-video-out), translate .45s var(--bkt-video-out);
  & span { padding: 3px 7px; border-radius: 6px; background: oklch(8% 0.01 var(--h) / .72); -webkit-box-decoration-break: clone; box-decoration-break: clone; }
  & i { font-style: normal; color: color-mix(in oklch, var(--bkt-video-text) 48%, transparent); transition: color .18s linear; }
  & i.is-said { color: var(--bkt-video-text); }
}
.bkt-video-card:is(.is-playing, .is-started):not(.no-cc) .bkt-video-cc { opacity: 1; translate: none; }

.bkt-video-bar {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 10px;
  padding: 26px 12px 12px;
  background: linear-gradient(to top, oklch(8% 0.01 var(--h) / .85), transparent);
  font-family: var(--bkt-video-mono); font-size: 11px; font-variant-numeric: tabular-nums;
  opacity: 0;
  transition: opacity .35s var(--bkt-video-out);
}
.bkt-video-card:is(.is-playing, .is-started) .bkt-video-bar, .bkt-video-card:focus-within .bkt-video-bar { opacity: 1; }
.bkt-video-seek {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 18px; margin: 0; background: transparent; cursor: pointer;
  accent-color: var(--bkt-video-accent);
  &::-webkit-slider-runnable-track { height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--bkt-video-accent) calc(var(--p) * 100%), oklch(100% 0 0 / .25) 0); }
  &::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -4.5px; border-radius: 50%; background: var(--bkt-video-text); border: 0; transition: scale .2s; }
  &::-moz-range-track { height: 3px; border-radius: 3px; background: oklch(100% 0 0 / .25); }
  &::-moz-range-progress { height: 3px; border-radius: 3px; background: var(--bkt-video-accent); }
  &::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: var(--bkt-video-text); border: 0; }
  &:focus-visible { outline: 2px solid var(--bkt-video-text); outline-offset: 2px; border-radius: 4px; }
  &:hover::-webkit-slider-thumb { scale: 1.25; }
}
.bkt-video-ccb {
  font: inherit; font-weight: 700; font-size: 10px; letter-spacing: .04em;
  color: var(--bkt-video-text); background: transparent;
  border: 1px solid color-mix(in oklch, var(--bkt-video-text) 45%, transparent);
  border-radius: 4px; padding: 2px 5px; cursor: pointer;
  &[aria-pressed="true"] { background: var(--bkt-video-text); color: oklch(14% 0.01 var(--h)); border-color: var(--bkt-video-text); }
  &:focus-visible { outline: 2px solid var(--bkt-video-accent); outline-offset: 2px; }
}

.bkt-video-meta { display: grid; gap: 8px; padding-inline: 2px; }
.bkt-video-pull { font-size: 17px; line-height: 1.3; font-weight: 600; letter-spacing: -.015em; text-wrap: balance; }
.bkt-video-who { display: grid; font-size: 13px; line-height: 1.35; & b { font-weight: 600; } & span { color: var(--bkt-video-muted); } }

/* playback motion: slow push-in on the set, a breathing head */
.bkt-video-card.is-playing:not(.is-stalled) .bkt-video-scene { animation: bkt-video-push 14s cubic-bezier(.3, 0, .7, 1) infinite alternate; }
.bkt-video-card.is-playing:not(.is-stalled) .bkt-video-face { animation: bkt-video-talk 2.6s cubic-bezier(.45, 0, .55, 1) infinite; }
.bkt-video-card.is-started:not(.is-playing) .bkt-video-scene { filter: saturate(.6) brightness(.8); }
@keyframes bkt-video-push { from { transform: scale(1); } to { transform: scale(1.07) translate(-1%, 1%); } }
@keyframes bkt-video-talk { 0%, 100% { rotate: 0deg; translate: 0 0; } 30% { rotate: -2deg; translate: 0 -3px; } 62% { rotate: 1.4deg; translate: 0 1px; } }

/* narrow: a snapping reel; the card nearest the centre of the scroller sits forward */
@supports (animation-timeline: view()) {
  .bkt-video-card {
    animation: bkt-video-focus linear both;
    animation-timeline: view(inline);
    animation-range: cover 0% cover 100%;
  }
  @keyframes bkt-video-focus {
    0% { scale: .9; }
    35%, 65% { scale: 1; }
    100% { scale: .9; }
  }
}

@container bkt-video (min-width: 760px) {
  .bkt-video-head { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); grid-template-areas: "kicker kicker" "title lede"; align-items: end; column-gap: 48px; }
  .bkt-video-track {
    grid-auto-flow: row;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-auto-columns: auto;
    overflow: visible;
    gap: clamp(14px, 2cqi, 26px);
    padding-block: 4px 0;
  }
  .bkt-video-card { animation: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-video-card { animation: none; }
  .bkt-video-card.is-playing .bkt-video-scene, .bkt-video-card.is-playing .bkt-video-face { animation: none; }
  .bkt-video-eq i { animation: none; transform: scaleY(.6); }
  .bkt-video-play, .bkt-video-play span, .bkt-video-lb::before, .bkt-video-lb::after, .bkt-video-cc, .bkt-video-card { transition-duration: .01s; }
}

