const DATA = [{"dur": 36, "name": "Maya Lindgren", "segs": [[0, 4.5, "We shot forty-one days across three countries last spring."], [4.5, 9.5, "Every call sheet, every change, went out from Slatehouse."], [9.5, 15, "When the ferry was cancelled in Bergen, I rebuilt the next two days in about twenty minutes,"], [15, 19.5, "and the whole crew had it on their phones before dinner."], [19.5, 25, "Nobody turned up at the wrong location. Not once."], [25, 31, "On a shoot that size, that is not a feature. That is the budget."], [31, 36, "I will not run a production without it now."]]}, {"dur": 41, "name": "Theo Mbeki-Shaw", "segs": [[0, 5, "My job is keeping two hundred people moving in the same direction."], [5, 10.5, "The schedule used to live in my head and a very tired spreadsheet."], [10.5, 16, "Now the strip board is live. I move a scene and the call times ripple out on their own."], [16, 22, "Cast get their pickups, catering gets its numbers, and nobody has to ring me."], [22, 28, "We wrapped series two four days early."], [28, 35, "Four days. On a TV budget, that is an episode of overtime we never spent."], [35, 41, "Honestly, my phone is quieter on set than it is at home."]]}, {"dur": 33, "name": "Ana Sofía Prieto", "segs": [[0, 5, "We run about sixty commercial shoots a year, usually three at once."], [5, 10, "Slatehouse gives us one view of every crew, every kit list and every day rate."], [10, 16, "Our producers stopped double-booking the same camera operator, which sounds small"], [16, 21, "until it is six in the morning and you are two people short."], [21, 27, "Invoices now reconcile against the call sheets on their own."], [27, 33, "Month-end close went from a week to an afternoon."]]}];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const cards = [...root.querySelectorAll('.bkt-video-card')].map((el, i) => ({
  el, d: DATA[i], t: 0, seg: -1, playing: false,
  btn: el.querySelector('.bkt-video-play'),
  seek: el.querySelector('.bkt-video-seek'),
  time: el.querySelector('.bkt-video-time'),
  cc: el.querySelector('.bkt-video-cc span'),
  ccb: el.querySelector('.bkt-video-ccb'),
  words: []
}));
const fmt = (s) => { s = Math.floor(s); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };

let active = null, raf = 0, last = 0, onScreen = false;

// Captions: one <i> per word; a word is "said" once the playhead passes its
// share of the segment, so the line fills in like karaoke.
function caption(c) {
  const segs = c.d.segs;
  let k = segs.findIndex((s) => c.t < s[1]);
  if (k < 0) k = segs.length - 1;
  if (k !== c.seg) {
    c.seg = k;
    c.cc.replaceChildren();
    c.words = segs[k][2].split(' ').map((w, j, arr) => {
      const i = document.createElement('i');
      i.textContent = w;
      c.cc.append(i);
      if (j < arr.length - 1) c.cc.append(' ');
      return i;
    });
  }
  const [a, b] = segs[k];
  const n = c.words.length;
  const f = (c.t - a) / (b - a);
  c.words.forEach((w, j) => w.classList.toggle('is-said', f * n * 1.08 >= j + 0.4));
}
function show(c) {
  c.seek.value = c.t.toFixed(1);
  c.seek.style.setProperty('--p', (c.t / c.d.dur).toFixed(4));
  c.time.textContent = fmt(c.t) + ' / ' + fmt(c.d.dur);
  caption(c);
}
function label(c) {
  const verb = c.playing ? 'Pause' : (c.t > 0 && c.t < c.d.dur ? 'Resume' : 'Play');
  c.btn.setAttribute('aria-label', verb + ' ' + c.d.name + '’s story, ' + Math.round(c.d.dur) + ' seconds');
}
function stop(c) {
  c.playing = false;
  c.el.classList.remove('is-playing');
  label(c);
  if (active === c) active = null;
}
function play(c) {
  if (active && active !== c) stop(active);
  if (c.t >= c.d.dur - 0.05) { c.t = 0; show(c); }
  c.playing = true;
  active = c;
  c.el.classList.add('is-playing', 'is-started');
  label(c);
  kick();
}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!active || !onScreen || document.hidden) { last = 0; return; }
  const dt = last ? Math.min(100, now - last) / 1000 : 0;
  last = now;
  const c = active;
  c.t = Math.min(c.d.dur, c.t + dt);
  show(c);
  if (c.t >= c.d.dur) { stop(c); return; }
  raf = requestAnimationFrame(step);
}
function kick() { if (!raf) { last = 0; raf = requestAnimationFrame(step); } }

cards.forEach((c) => {
  show(c);
  label(c);
  c.btn.addEventListener('click', () => (c.playing ? stop(c) : play(c)));
  c.seek.addEventListener('input', () => {
    c.t = Math.max(0, Math.min(c.d.dur, parseFloat(c.seek.value) || 0));
    c.el.classList.add('is-started');
    show(c);
    label(c);
  });
  c.ccb.addEventListener('click', () => {
    const on = c.ccb.getAttribute('aria-pressed') !== 'true';
    c.ccb.setAttribute('aria-pressed', String(on));
    c.el.classList.toggle('no-cc', !on);
  });
  // clicking the picture toggles playback, like a real player
  c.el.querySelector('.bkt-video-frame').addEventListener('click', (e) => {
    if (e.target.closest('button, input')) return;
    c.playing ? stop(c) : play(c);
  });
  // K toggles from any control inside the card; Escape stops
  c.el.addEventListener('keydown', (e) => {
    if (e.key === 'k' || e.key === 'K') { e.preventDefault(); c.playing ? stop(c) : play(c); }
    else if (e.key === 'Escape' && c.playing) { stop(c); c.btn.focus(); }
  });
});

const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  cards.forEach((c) => c.el.classList.toggle('is-stalled', !onScreen));
  kick();
}, { threshold: 0.15 });
io.observe(root);

const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); io.disconnect(); return; }
  cards.forEach((c) => c.el.classList.toggle('is-stalled', document.hidden || !onScreen));
  kick();
};
document.addEventListener('visibilitychange', onVis);

css:
@property --bkt-metrics-n { syntax: "<integer>"; inherits: false; initial-value: 0; }

.bkt-metrics {
  --bkt-metrics-bg: oklch(17.5% 0.006 255);
  --bkt-metrics-text: oklch(94.5% 0.006 255);
  --bkt-metrics-accent: oklch(81% 0.155 74);
  --bkt-metrics-before: oklch(64% 0.02 255);
  --bkt-metrics-muted: color-mix(in oklch, var(--bkt-metrics-text) 55%, var(--bkt-metrics-bg));
  --bkt-metrics-line: color-mix(in oklch, var(--bkt-metrics-text) 10%, transparent);
  --bkt-metrics-panel: color-mix(in oklch, var(--bkt-metrics-text) 3.5%, var(--bkt-metrics-bg));
  --bkt-metrics-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkt-metrics-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  container-name: bkt-metrics;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkt-metrics-bg);
  color: var(--bkt-metrics-text);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dd, figure, blockquote) { margin: 0; padding: 0; }
}
.bkt-metrics-in {
  padding: clamp(36px, 6.5cqi, 84px) clamp(16px, 5cqi, 64px);
  display: grid; gap: clamp(24px, 3.5cqi, 40px);
  background: radial-gradient(60% 55% at 82% 38%, color-mix(in oklch, var(--bkt-metrics-accent) 8%, transparent), transparent 70%);
}

.bkt-metrics-head { display: grid; gap: 12px 40px; grid-template-areas: "kicker" "title" "tabs"; }
.bkt-metrics-kicker {
  grid-area: kicker;
  display: flex; align-items: center; gap: 8px;
  font-family: var(--bkt-metrics-mono); font-size: 11.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--bkt-metrics-accent);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkt-metrics-title { grid-area: title; font-size: clamp(28px, 3.3cqi + 14px, 48px); font-weight: 650; letter-spacing: -.035em; line-height: 1.04; text-wrap: balance; max-width: 18ch; }

.bkt-metrics-tabs {
  grid-area: tabs;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 1px solid var(--bkt-metrics-line); border-radius: 12px;
  padding: 4px; gap: 4px;
  background: var(--bkt-metrics-panel);
  margin-top: 8px;
}
.bkt-metrics-tab {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  font: inherit; color: var(--bkt-metrics-muted); text-align: left;
  background: transparent; border: 0; border-radius: 8px;
  padding: 10px 10px; cursor: pointer; min-width: 0;
  transition: background-color .3s var(--bkt-metrics-out), color .3s;
  flex-direction: column; text-align: center; gap: 5px;
  & svg { width: 26px; height: 26px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: stroke .3s; }
  & span { min-width: 0; max-width: 100%; }
  & b { display: block; font-weight: 600; font-size: 12px; line-height: 1.2; color: var(--bkt-metrics-text); text-wrap: balance; }
  & small { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; font-family: var(--bkt-metrics-mono); font-size: 11px; }
  &:hover { color: var(--bkt-metrics-text); background: var(--bkt-metrics-line); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--bkt-metrics-accent) 14%, transparent); color: var(--bkt-metrics-text); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkt-metrics-accent) 45%, transparent); }
  &[aria-selected="true"] svg { stroke: var(--bkt-metrics-accent); }
  &:focus-visible { outline: 2px solid var(--bkt-metrics-accent); outline-offset: 2px; }
}
.bkt-metrics-tab span b + small { color: var(--bkt-metrics-muted); }

.bkt-metrics-panel {
  display: grid; gap: 20px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "story" "chart" "stats";
}
.bkt-metrics-story { grid-area: story; display: grid; gap: 16px; align-content: start; }
.bkt-metrics-sector { font-family: var(--bkt-metrics-mono); font-size: 11.5px; color: var(--bkt-metrics-muted); letter-spacing: .04em; }
.bkt-metrics-quote { font-size: clamp(17px, .8cqi + 13px, 21px); line-height: 1.42; letter-spacing: -.012em; text-wrap: pretty; font-weight: 450; }
.bkt-metrics-who { display: flex; flex-wrap: wrap; gap: 4px 8px; font-size: 13.5px; & b { font-weight: 600; } & span { color: var(--bkt-metrics-muted); } }
.bkt-metrics-big { display: flex; align-items: flex-end; gap: 16px; padding-top: 18px; border-top: 1px solid var(--bkt-metrics-line); }
.bkt-metrics-num {
  display: flex; align-items: flex-start;
  font-size: clamp(64px, 6cqi + 36px, 112px); font-weight: 680; line-height: .82; letter-spacing: -.055em;
  color: var(--bkt-metrics-accent);
  font-variant-numeric: tabular-nums;
}
.bkt-metrics-sign { font-weight: 400; margin-right: .03em; }
.bkt-metrics-pc { font-size: .42em; font-weight: 500; letter-spacing: 0; margin: .08em 0 0 .06em; }
.bkt-metrics-ctr {
  transition: --bkt-metrics-n 1.2s cubic-bezier(.2, .8, .2, 1);
  counter-reset: bkt-metrics-n var(--bkt-metrics-n);
  &::after { content: counter(bkt-metrics-n); }
}
.bkt-metrics-label {
  display: grid; gap: 2px; padding-bottom: 4px;
  font-size: 15px; font-weight: 600;
  & small { font-family: var(--bkt-metrics-mono); font-size: 11.5px; font-weight: 400; color: var(--bkt-metrics-muted); font-variant-numeric: tabular-nums; }
}
.bkt-metrics-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkt-metrics-chart {
  grid-area: chart;
  display: grid; gap: 10px;
  border: 1px solid var(--bkt-metrics-line); border-radius: 14px;
  background: var(--bkt-metrics-panel);
  padding: 14px 14px 10px;
  & figcaption { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 14px; font-family: var(--bkt-metrics-mono); font-size: 11px; color: var(--bkt-metrics-muted); }
}
.bkt-metrics-ctitle { color: var(--bkt-metrics-text); }
.bkt-metrics-legend {
  display: inline-flex; align-items: center; gap: 6px;
  & i { width: 14px; height: 2px; border-radius: 2px; background: var(--bkt-metrics-before); margin-left: 6px; }
  & i.is-a { background: var(--bkt-metrics-accent); }
}
.bkt-metrics-plot {
  position: relative;
  height: clamp(200px, 22cqi, 300px);
  margin-left: 40px;
  cursor: crosshair;
  touch-action: pan-y;
  outline: none;
  &:focus-visible { box-shadow: 0 0 0 2px var(--bkt-metrics-accent); border-radius: 4px; }
}
.bkt-metrics-ticks {
  position: absolute; inset: 0; pointer-events: none;
  & span {
    position: absolute; left: 0; right: 0; top: var(--y);
    border-top: 1px dashed var(--bkt-metrics-line);
    font-family: var(--bkt-metrics-mono); font-size: 10px; color: var(--bkt-metrics-muted); font-variant-numeric: tabular-nums;
  }
  & span::before { content: attr(data-v); position: absolute; right: calc(100% + 8px); top: -.7em; white-space: nowrap; }
}
.bkt-metrics-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.bkt-metrics-svg path { vector-effect: non-scaling-stroke; fill: none; stroke-linejoin: round; stroke-linecap: round; }
.bkt-metrics-lb { stroke: var(--bkt-metrics-before); stroke-width: 2; }
.bkt-metrics-la { stroke: var(--bkt-metrics-accent); stroke-width: 2.5; }
.bkt-metrics-svg .bkt-metrics-area { fill: color-mix(in oklch, var(--bkt-metrics-accent) 13%, transparent); stroke: none; }
.bkt-metrics-avg { stroke: none; }
.bkt-metrics-cut {
  position: absolute; top: -6px; bottom: 0; left: var(--x);
  border-left: 1px dashed color-mix(in oklch, var(--bkt-metrics-text) 40%, transparent);
  & span { position: absolute; top: 0; left: 6px; font-family: var(--bkt-metrics-mono); font-size: 10px; color: var(--bkt-metrics-text); background: var(--bkt-metrics-panel); padding: 0 4px; white-space: nowrap; }
}
.bkt-metrics-avgl {
  position: absolute; top: var(--y); left: var(--l); width: var(--w);
  border-top: 1px dotted var(--bkt-metrics-before);
  font-family: var(--bkt-metrics-mono); font-size: 10px; color: var(--bkt-metrics-before); font-variant-numeric: tabular-nums;
  &::after { content: attr(data-v); position: absolute; left: 4px; bottom: 4px; white-space: nowrap; padding: 1px 5px; border-radius: 4px; background: color-mix(in oklch, var(--bkt-metrics-panel) 88%, transparent); }
  &.is-a { border-color: var(--bkt-metrics-accent); color: var(--bkt-metrics-accent); }
  &.is-a::after { left: auto; right: 4px; bottom: auto; top: 4px; }
}
.bkt-metrics-cross {
  position: absolute; top: 0; bottom: 0; left: var(--x, 100%);
  border-left: 1px solid color-mix(in oklch, var(--bkt-metrics-text) 30%, transparent);
  opacity: 0; transition: opacity .2s;
  pointer-events: none;
  & i { position: absolute; left: -5px; top: var(--y); width: 9px; height: 9px; margin-top: -4.5px; border-radius: 50%; background: var(--bkt-metrics-bg); border: 2px solid var(--c, var(--bkt-metrics-accent)); }
  & b {
    position: absolute; top: calc(var(--y) - 40px); left: 10px;
    font: 500 11.5px/1 var(--bkt-metrics-mono); font-variant-numeric: tabular-nums;
    padding: 6px 8px; border-radius: 6px; white-space: nowrap;
    background: var(--bkt-metrics-text); color: var(--bkt-metrics-bg);
  }
  &.is-flip b { left: auto; right: 10px; }
}
.bkt-metrics-plot:is(:hover, :focus-visible) .bkt-metrics-cross { opacity: 1; }
.bkt-metrics-weeks {
  position: relative; height: 14px; margin-left: 40px;
  font-family: var(--bkt-metrics-mono); font-size: 10px; color: var(--bkt-metrics-muted);
  & span { position: absolute; top: 0; white-space: nowrap; }
  & span:nth-child(2) { translate: calc(-100% - 6px) 0; }
  & span:nth-child(3) { translate: 6px 0; color: var(--bkt-metrics-accent); }
  & span:last-child { translate: -100% 0; }
}

.bkt-metrics-stats {
  grid-area: stats;
  display: grid; grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--bkt-metrics-line); border-radius: 14px; overflow: hidden;
}
.bkt-metrics-cell {
  padding: 14px 16px; display: grid; gap: 6px;
  & + & { border-top: 1px solid var(--bkt-metrics-line); }
  & dt { font-size: 12px; color: var(--bkt-metrics-muted); }
  & dd { display: flex; align-items: baseline; gap: 8px; font-variant-numeric: tabular-nums; flex-wrap: wrap; }
  & s { text-decoration: none; color: var(--bkt-metrics-muted); font-size: 15px; }
  & svg { width: 14px; height: 14px; fill: none; stroke: var(--bkt-metrics-muted); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; align-self: center; }
  & b { font-size: 22px; font-weight: 650; letter-spacing: -.02em; }
  & em { font-style: normal; margin-left: auto; font-family: var(--bkt-metrics-mono); font-size: 11px; padding: 3px 6px; border-radius: 5px; color: var(--bkt-metrics-accent); background: color-mix(in oklch, var(--bkt-metrics-accent) 12%, transparent); }
}

@container bkt-metrics (min-width: 640px) {
  .bkt-metrics-tab { flex-direction: row; justify-content: flex-start; text-align: left; gap: 10px; padding: 10px 12px; }
  .bkt-metrics-tab b { font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .bkt-metrics-tab small { position: static; display: block; width: auto; height: auto; clip-path: none; text-overflow: ellipsis; }
  .bkt-metrics-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bkt-metrics-cell + .bkt-metrics-cell { border-top: 0; border-left: 1px solid var(--bkt-metrics-line); }
}
@container bkt-metrics (min-width: 980px) {
  .bkt-metrics-head { grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); grid-template-areas: "kicker kicker" "title tabs"; align-items: end; }
  .bkt-metrics-tabs { margin-top: 0; }
  .bkt-metrics-panel {
    grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
    grid-template-areas: "story chart" "stats stats";
    column-gap: clamp(28px, 4cqi, 56px);
    row-gap: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-metrics-ctr { transition: none; }
  .bkt-metrics-tab, .bkt-metrics-cross { transition: none; }
}

