const DATA = [{"name": "Orchard Freight", "sector": "Logistics · 1.2B requests / month", "quote": "We moved our dispatch APIs onto Relaypoint over a single weekend. The drivers noticed before our dashboards did — the route planner simply stopped hanging at the depot.", "who": "Callum Reyes", "role": "VP Engineering", "metric": "p95 API latency", "unit": "ms", "before": 840, "after": 320, "pct": 62, "series": [839, 814, 884, 804, 868, 845, 802, 864, 389, 348, 307, 297, 308, 323, 293, 295], "ymax": 1000, "stats": [["Infra spend / month", "$48.0k", "$29.0k", "−40%"], ["On-call pages / week", "23", "4", "−83%"], ["Cutover", "Fri 18:00", "Sun 21:40", "1 weekend"]]}, {"name": "Kitebase", "sector": "Developer platform · 38k apps", "quote": "Our customers deploy to us, and we deploy to Relaypoint. Cold starts were the top complaint in our forum for two years. Six weeks after cutover, nobody brings them up.", "who": "Hana Sato", "role": "Co-founder & CTO", "metric": "Cold-start time", "unit": "ms", "before": 1900, "after": 410, "pct": 78, "series": [1878, 1911, 2020, 1882, 1895, 1919, 1799, 1896, 524, 459, 385, 384, 365, 406, 399, 358], "ymax": 2400, "stats": [["Edge regions", "3", "14", "+11"], ["Egress bill / month", "$112k", "$71k", "−37%"], ["Cold-start forum threads / month", "64", "3", "−95%"]]}, {"name": "Mallow Health", "sector": "Patient portal · 2.3M patients", "quote": "In healthcare a slow page is a missed appointment. Relaypoint cut our portal’s tail latency by more than two thirds, and the compliance review took exactly one meeting.", "who": "Priscilla Nwosu", "role": "Director of Digital", "metric": "p95 page load", "unit": "ms", "before": 1240, "after": 380, "pct": 69, "series": [1308, 1313, 1302, 1148, 1245, 1213, 1234, 1157, 468, 412, 371, 370, 342, 343, 375, 359], "ymax": 1500, "stats": [["Portal uptime", "99.71%", "99.99%", "+0.28 pts"], ["“Slow portal” tickets / month", "310", "42", "−86%"], ["Security review", "6 weeks", "1 meeting", "approved"]]}];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const $ = (s) => root.querySelector(s);
const tabs = [...root.querySelectorAll('.bkt-metrics-tab')];
const panel = $('.bkt-metrics-panel');
const story = $('.bkt-metrics-story');
const ctr = $('.bkt-metrics-ctr');
const plot = $('.bkt-metrics-plot');
const svg = $('.bkt-metrics-svg');
const cross = $('.bkt-metrics-cross');
const tip = cross.querySelector('b');
const ticks = $('.bkt-metrics-ticks');
const cut = $('.bkt-metrics-cut');
const avgB = $('.bkt-metrics-avgl.is-b'), avgA = $('.bkt-metrics-avgl.is-a');
const stats = $('.bkt-metrics-stats');
const N = 16, SPLIT = 8;
const uid = Math.random().toString(36).slice(2, 8);
panel.id = 'bkt-metrics-panel-' + uid;
tabs.forEach((t, i) => { t.id = 'bkt-metrics-tab-' + uid + '-' + i; t.setAttribute('aria-controls', panel.id); });
panel.setAttribute('aria-labelledby', tabs[0].id);

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const fmtN = (n) => n.toLocaleString('en-US');
const X = (i) => (i / (N - 1)) * 1000;
let cur = 0, week = N - 1;

function draw(c) {
  const Y = (v) => 400 - (v / c.ymax) * 400;
  const pts = c.series.map((v, i) => [X(i), Y(v)]);
  const line = (a) => a.map((p, k) => (k ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
  // the before line runs into the first "after" point so the two segments meet
  svg.querySelector('.bkt-metrics-lb').setAttribute('d', line(pts.slice(0, SPLIT + 1)));
  svg.querySelector('.bkt-metrics-la').setAttribute('d', line(pts.slice(SPLIT)));
  const aft = pts.slice(SPLIT);
  svg.querySelector('.bkt-metrics-area').setAttribute('d', line(aft) + ' L' + aft[aft.length - 1][0] + ' 400 L' + aft[0][0] + ' 400 Z');
  const step = c.ymax / 4;
  ticks.innerHTML = [1, 2, 3].map((k) => '<span style="--y:' + (100 - (k * step / c.ymax) * 100) + '%" data-v="' + fmtN(k * step) + '"></span>').join('') +
    '<span style="--y:100%" data-v="0"></span>';
  const cutX = (X(SPLIT - 1) + X(SPLIT)) / 20;
  cut.style.setProperty('--x', cutX + '%');
  const pos = (el, v, l, w) => { el.style.setProperty('--y', (100 - v / c.ymax * 100) + '%'); el.style.setProperty('--l', l + '%'); el.style.setProperty('--w', w + '%'); el.dataset.v = 'avg ' + fmtN(v); };
  pos(avgB, c.before, 0, cutX);
  pos(avgA, c.after, cutX, 100 - cutX);
  if (!reduce.matches) {
    svg.animate([{ clipPath: 'inset(0 100% 0 0)' }, { clipPath: 'inset(0 0 0 0)' }], { duration: 1100, easing: 'cubic-bezier(.65, 0, .35, 1)' });
    [avgB, avgA].forEach((el, k) => el.animate([{ opacity: 0, transform: 'scaleX(0)' }, { opacity: 1, transform: 'none' }], { duration: 600, delay: 500 + k * 350, easing: 'cubic-bezier(.16, 1, .3, 1)', fill: 'backwards' }));
    avgB.style.transformOrigin = '0 0'; avgA.style.transformOrigin = '0 0';
  }
  setWeek(week);
}

function setWeek(i) {
  const c = DATA[cur];
  week = Math.max(0, Math.min(N - 1, i));
  const v = c.series[week];
  const after = week >= SPLIT;
  cross.style.setProperty('--x', (week / (N - 1)) * 100 + '%');
  cross.style.setProperty('--y', (100 - v / c.ymax * 100) + '%');
  cross.style.setProperty('--c', after ? 'var(--bkt-metrics-accent)' : 'var(--bkt-metrics-before)');
  cross.classList.toggle('is-flip', week > N - 5);
  tip.textContent = 'Wk ' + (week + 1) + ' · ' + fmtN(v) + ' ' + c.unit;
  plot.setAttribute('aria-valuenow', String(week + 1));
  plot.setAttribute('aria-valuetext', 'Week ' + (week + 1) + ', ' + (after ? 'on Relaypoint' : 'before cutover') + ': ' + fmtN(v) + ' ' + c.unit);
}

function fill(c) {
  story.querySelector('.bkt-metrics-sector').textContent = c.sector;
  story.querySelector('.bkt-metrics-quote p').textContent = c.quote;
  story.querySelector('.bkt-metrics-who').innerHTML = '<b>' + esc(c.who) + '</b><span>' + esc(c.role) + ', ' + esc(c.name) + '</span>';
  story.querySelector('.bkt-metrics-sr').textContent = c.pct + '% lower ';
  story.querySelector('.bkt-metrics-mname').textContent = c.metric;
  story.querySelector('.bkt-metrics-label small').textContent = fmtN(c.before) + ' ' + c.unit + ' → ' + fmtN(c.after) + ' ' + c.unit + ', 8-week averages';
  $('.bkt-metrics-ctitle').textContent = 'Weekly ' + c.metric.charAt(0).toLowerCase() + c.metric.slice(1);
  stats.innerHTML = c.stats.map((s, i) => '<div class="bkt-metrics-cell" style="--i:' + i + '"><dt>' + esc(s[0]) + '</dt><dd><s>' + esc(s[1]) +
    '</s><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10M9.5 4.5 13 8l-3.5 3.5"/></svg><b>' + esc(s[2]) + '</b><em>' + esc(s[3]) + '</em></dd></div>').join('');
}

function select(i, focus) {
  if (i === cur) return;
  cur = i;
  tabs.forEach((t, k) => { const on = k === i; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; });
  if (focus) tabs[i].focus();
  panel.setAttribute('aria-labelledby', tabs[i].id);
  const c = DATA[i];
  ctr.style.setProperty('--bkt-metrics-n', c.pct);   // @property integer: the counter rolls between values
  if (reduce.matches) { fill(c); draw(c); return; }
  const parts = [story.querySelector('.bkt-metrics-quote'), story.querySelector('.bkt-metrics-who'), story.querySelector('.bkt-metrics-sector'), story.querySelector('.bkt-metrics-label'), stats];
  const outs = parts.map((el) => el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(-6px)' }], { duration: 180, easing: 'cubic-bezier(.4, 0, 1, 1)', fill: 'forwards' }));
  draw(c);
  Promise.all(outs.map((a) => a.finished)).then(() => {
    if (cur !== i) return;
    fill(c);
    outs.forEach((a) => a.cancel());
    parts.forEach((el, k) => el.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 520, delay: k * 40, easing: 'cubic-bezier(.16, 1, .3, 1)', fill: 'backwards' }));
    [...stats.children].forEach((el, k) => el.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 520, delay: 160 + k * 70, easing: 'cubic-bezier(.16, 1, .3, 1)', fill: 'backwards' }));
  }, () => {});
}

const list = $('.bkt-metrics-tabs');
list.addEventListener('click', (e) => { const t = e.target.closest('.bkt-metrics-tab'); if (t) select(tabs.indexOf(t)); });
list.addEventListener('keydown', (e) => {
  let n = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = (cur + 1) % tabs.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = (cur + tabs.length - 1) % tabs.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = tabs.length - 1;
  if (n === null) return;
  e.preventDefault();
  select(n, true);
});

plot.addEventListener('pointermove', (e) => {
  const r = plot.getBoundingClientRect();
  setWeek(Math.round(((e.clientX - r.left) / r.width) * (N - 1)));
});
plot.addEventListener('keydown', (e) => {
  const m = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 };
  if (e.key in m) { e.preventDefault(); setWeek(week + m[e.key]); }
  else if (e.key === 'Home') { e.preventDefault(); setWeek(0); }
  else if (e.key === 'End') { e.preventDefault(); setWeek(N - 1); }
  else if (e.key === 'PageUp' || e.key === 'PageDown') { e.preventDefault(); setWeek(e.key === 'PageUp' ? SPLIT : SPLIT - 1); }
});

// first view: the counter rolls up from zero and the line draws in
draw(DATA[0]);
let seen = false;
if (!reduce.matches) ctr.style.setProperty('--bkt-metrics-n', 0);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  if (seen || !es[es.length - 1].isIntersecting) return;
  seen = true;
  io.disconnect();
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    ctr.style.setProperty('--bkt-metrics-n', DATA[cur].pct);
    draw(DATA[cur]);
  });
}, { threshold: 0.25 });
io.observe(root);

