js:
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const fmt = (n) => n.toLocaleString('en-US');
const total = root.querySelector('.bkt-posts-tot');
let likes = 0;
root.querySelectorAll('.bkt-posts-btn.is-like').forEach((b) => { likes += Number(b.dataset.n); });

// roll a number: the old value slides up and out, the new one rises in
function roll(el, value, up) {
  el.textContent = fmt(value);
  if (reduce.matches) return;
  el.animate(
    [{ transform: 'translateY(' + (up ? '70%' : '-70%') + ')', opacity: 0 }, { transform: 'none', opacity: 1 }],
    { duration: 380, easing: 'cubic-bezier(.22, 1, .36, 1)' }
  );
}

root.addEventListener('click', (e) => {
  const btn = e.target.closest('.bkt-posts-btn');
  if (btn) {
    const on = btn.getAttribute('aria-pressed') !== 'true';
    btn.setAttribute('aria-pressed', String(on));
    const n = Number(btn.dataset.n) + (on ? 1 : 0);
    roll(btn.querySelector('.bkt-posts-n'), n, on);
    if (btn.classList.contains('is-like')) {
      likes += on ? 1 : -1;
      roll(total, likes, on);
      btn.classList.remove('is-pop');
      if (on && !reduce.matches) {
        void btn.offsetWidth;            // restart the burst keyframes
        btn.classList.add('is-pop');
      }
    }
    return;
  }
  if (e.target.closest('.bkt-posts-all')) {
    root.classList.add('is-all');
    const next = root.querySelector('.bkt-posts-card:nth-child(5) .bkt-posts-btn');
    if (next) next.focus({ preventScroll: true });
    return;
  }
  const more = e.target.closest('.bkt-posts-more');
  if (more) {
    const open = more.getAttribute('aria-expanded') !== 'true';
    more.setAttribute('aria-expanded', String(open));
    const who = more.querySelector('.bkt-posts-mt');
    who.textContent = (open ? 'Hide' : 'Show') + who.textContent.replace(/^(Show|Hide)/, '');
  }
});
root.addEventListener('animationend', (e) => {
  if (e.animationName === 'bkt-posts-pop') e.target.closest('.bkt-posts-btn').classList.remove('is-pop');
});

// drop the cards onto the board the first time the section is seen
if (!reduce.matches) {
  root.classList.add('is-armed');
  const io = new IntersectionObserver((es) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (!es[es.length - 1].isIntersecting) return;
    io.disconnect();
    requestAnimationFrame(() => {
      if (!root.isConnected) return;
      root.classList.add('is-in');
      root.classList.remove('is-armed');
      setTimeout(() => root.classList.remove('is-in'), 1400);
    });
  }, { threshold: 0.12 });
  io.observe(root);
}

