  --bkt-logos-dur: 6.5s;
  --bkt-logos-b: 2px solid var(--bkt-logos-ink);
  --bkt-logos-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkt-logos-snap: cubic-bezier(.7, 0, .3, 1);
  container-type: inline-size;
  container-name: bkt-logos;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkt-logos-paper);
  color: var(--bkt-logos-ink);
  font: 500 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, blockquote) { margin: 0; padding: 0; }
}
.bkt-logos-in { padding: clamp(32px, 6cqi, 80px) clamp(16px, 5cqi, 64px); display: grid; gap: 22px; }

.bkt-logos-head {
  display: grid; gap: 16px;
  grid-template-areas: "title" "meta";
  border-bottom: 6px solid var(--bkt-logos-ink);
  padding-bottom: 18px;
}
.bkt-logos-title {
  grid-area: title;
  font-size: clamp(36px, 6.2cqi + 12px, 96px);
  font-weight: 900; line-height: .9; letter-spacing: -.055em; text-transform: uppercase;
  text-wrap: balance;
  & span { background: var(--bkt-logos-acid); padding: 0 .08em; box-shadow: 0 0 0 2px var(--bkt-logos-ink); margin-inline: .04em; }
}
.bkt-logos-meta {
  grid-area: meta;
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 20px;
  font-family: var(--bkt-logos-mono); font-size: 11.5px; font-weight: 500; text-transform: uppercase; letter-spacing: .06em; line-height: 1.3;
}
.bkt-logos-rec { font-variant-numeric: tabular-nums; & b { font-size: 22px; font-weight: 800; letter-spacing: -.02em; } }
.bkt-logos-hold {
  display: inline-flex; align-items: center; gap: 8px;
