  border-top: var(--bkt-logos-b); border-left: var(--bkt-logos-b);
}
.bkt-logos-tab {
  position: relative;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
  min-height: 92px; padding: 14px 8px 16px;
  font: inherit; color: var(--bkt-logos-ink);
  background: var(--bkt-logos-paper);
  border: 0; border-right: var(--bkt-logos-b); border-bottom: var(--bkt-logos-b);
  cursor: pointer;
  transition: background-color .15s steps(2), transform .15s var(--bkt-logos-snap), box-shadow .15s var(--bkt-logos-snap);
  & svg { width: 30px; height: 30px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: square; stroke-linejoin: miter; }
  & svg .is-fill { fill: currentColor; }
  &:hover { background: color-mix(in oklch, var(--bkt-logos-acid) 45%, var(--bkt-logos-paper)); }
  &:focus-visible { outline: 3px solid var(--bkt-logos-signal); outline-offset: -6px; z-index: 2; }
  &[aria-selected="true"] {
    background: var(--bkt-logos-acid);
    z-index: 1;
    transform: translate(-4px, -4px);
    box-shadow: 0 0 0 2px var(--bkt-logos-ink), 4px 4px 0 2px var(--bkt-logos-ink);
  }
}
.bkt-logos-word { font-size: 13px; line-height: 1; white-space: nowrap; }
.is-oxbow .bkt-logos-word { font-weight: 900; letter-spacing: .16em; }
.is-tallgrass .bkt-logos-word { font-weight: 700; font-style: italic; letter-spacing: -.02em; font-size: 15px; }
.is-nimbl .bkt-logos-word { font-weight: 900; letter-spacing: -.06em; font-size: 17px; }
.is-quarry .bkt-logos-word { font-family: var(--bkt-logos-mono); font-weight: 700; letter-spacing: .02em; font-size: 12px; }
.is-luma .bkt-logos-word { font-weight: 450; letter-spacing: .02em; font-size: 14.5px; }
.is-halyard .bkt-logos-word { font-weight: 800; letter-spacing: .3em; font-size: 11.5px; margin-right: -.3em; }
.bkt-logos-run {
  position: absolute; left: 0; right: 0; bottom: 0; height: 5px;
  background: var(--bkt-logos-ink);
  transform: scaleX(0); transform-origin: 0 50%;
}
.bkt-logos-tab[aria-selected="true"] .bkt-logos-run { animation: bkt-logos-run var(--bkt-logos-dur) linear forwards; }
.bkt-logos:is(.is-held, .is-off) .bkt-logos-tab[aria-selected="true"] .bkt-logos-run,
.bkt-logos:has(.bkt-logos-panel:hover, .bkt-logos-tabs:hover, :focus-visible) .bkt-logos-tab[aria-selected="true"] .bkt-logos-run { animation-play-state: paused; }
@keyframes bkt-logos-run { to { transform: scaleX(1); } }

.bkt-logos-panel {
  position: relative; overflow: hidden;
  border: var(--bkt-logos-b);
  box-shadow: 8px 8px 0 var(--bkt-logos-ink);
  background: var(--bkt-logos-paper);
  margin: 6px 8px 8px 0;
}
.bkt-logos-body {
  display: grid; gap: 18px;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-areas: "num metric" "quote quote" "by by";
  padding: 20px;
  align-items: start;
}
.bkt-logos-num {
  grid-area: num;
  font-size: clamp(76px, 11cqi + 20px, 168px); font-weight: 900; line-height: .78; letter-spacing: -.07em;
  color: transparent; -webkit-text-stroke: 2px var(--bkt-logos-ink);
  font-variant-numeric: tabular-nums;
}
.bkt-logos-q {
  grid-area: quote;
  font-size: clamp(20px, 1.6cqi + 14px, 32px); font-weight: 650; line-height: 1.16; letter-spacing: -.028em;
  text-wrap: pretty;
}
.bkt-logos-by {
  grid-area: by;
  font-family: var(--bkt-logos-mono); font-size: 12px; text-transform: uppercase; letter-spacing: .06em;
  border-top: var(--bkt-logos-b); padding-top: 12px;
  & b { background: var(--bkt-logos-ink); color: var(--bkt-logos-paper); padding: 2px 6px; font-weight: 700; }
}
.bkt-logos-metric {
  grid-area: metric;
  display: grid; gap: 6px; justify-items: start;
  font-family: var(--bkt-logos-mono);
}
.bkt-logos-ml { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; }
.bkt-logos-mv {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px;
  font-variant-numeric: tabular-nums;
  & s { font-size: 15px; text-decoration-thickness: 2px; text-decoration-color: var(--bkt-logos-signal); }
  & svg { width: 18px; height: 18px; fill: none; stroke: var(--bkt-logos-ink); stroke-width: 2.4; stroke-linecap: square; }
  & b { font-family: system-ui, sans-serif; font-size: clamp(30px, 2.4cqi + 20px, 54px); font-weight: 900; letter-spacing: -.05em; line-height: 1; background: var(--bkt-logos-acid); padding: 2px 8px 4px; box-shadow: 0 0 0 2px var(--bkt-logos-ink); }
}
.bkt-logos-md { font-size: 12px; font-weight: 700; padding: 3px 7px; background: var(--bkt-logos-ink); color: var(--bkt-logos-acid); }

.bkt-logos-shutter {
  position: absolute; inset: 0; z-index: 3;
  background:
    repeating-linear-gradient(-45deg, transparent 0 14px, color-mix(in oklch, var(--bkt-logos-acid) 22%, transparent) 14px 16px),
    var(--bkt-logos-ink);
  transform: scaleX(0); transform-origin: 0 50%;
  pointer-events: none;
}

@container bkt-logos (min-width: 760px) {
  .bkt-logos-head { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title meta"; align-items: end; }
  .bkt-logos-meta { flex-direction: column; align-items: flex-end; text-align: right; }
  .bkt-logos-tabs { grid-template-columns: repeat(6, minmax(0, 1fr)); }
  .bkt-logos-body {
    grid-template-columns: auto minmax(0, 1fr) minmax(200px, .5fr);
    grid-template-areas: "num quote metric" "num by metric";
    column-gap: clamp(20px, 3cqi, 44px);
    padding: clamp(22px, 3cqi, 36px);
  }
  .bkt-logos-metric { border-left: var(--bkt-logos-b); padding-left: clamp(16px, 2.4cqi, 28px); align-self: stretch; align-content: center; }
  .bkt-logos-by { align-self: end; }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-logos-tab[aria-selected="true"] .bkt-logos-run { animation: none; transform: scaleX(1); }
  .bkt-logos-hold { display: none; }
  .bkt-logos-tab, .bkt-logos-hold { transition: none; }
}

