const DATA = [{"word": "OXBOW", "q": "Our monorepo has 2,300 packages. Forgeline only rebuilds what actually changed, so the median PR check fell from thirty-one minutes to four.", "who": "Ines Varga", "role": "Staff engineer", "metric": "Median PR check", "a": "31:00", "b": "04:00", "delta": "−87%"}, {"word": "tallgrass", "q": "We had a “no merging after 3 p.m.” rule because the pipeline was slower than our patience. The rule is gone. So is the 6 p.m. deploy panic.", "who": "Kwame Asante", "role": "Engineering manager", "metric": "Deploys per day", "a": "3", "b": "22", "delta": "7.3×"}, {"word": "nimbl.", "q": "Flaky-test quarantine paid for itself in the first week. Nobody re-runs a red build “just to see” any more — it tells us which test lied.", "who": "Sara Lindholm", "role": "Head of platform", "metric": "Re-runs per week", "a": "410", "b": "36", "delta": "−91%"}, {"word": "QUARRY&CO", "q": "Remote cache hits sit at 94%. Our laptops are quiet, and our CI bill is even quieter than our laptops.", "who": "Tom Becker", "role": "CTO", "metric": "CI spend per month", "a": "$18.4k", "b": "$6.1k", "delta": "−67%"}, {"word": "Lumacraft", "q": "Forty-gigabyte game builds on every single commit, done in eleven minutes. I did not think that sentence was legal.", "who": "Mei Takahashi", "role": "Build engineer", "metric": "Full game build", "a": "58 min", "b": "11 min", "delta": "−81%"}, {"word": "HALYARD", "q": "We moved 140 pipelines over in nine working days. The config is plain text, and the docs describe the product we actually have.", "who": "Rafael Duarte", "role": "Platform lead", "metric": "Pipelines migrated", "a": "140", "b": "9 days", "delta": "1 sprint"}];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const $ = (s) => root.querySelector(s);
const tabs = [...root.querySelectorAll('.bkt-logos-tab')];
const list = $('.bkt-logos-tabs');
const panel = $('.bkt-logos-panel');
const body = $('.bkt-logos-body');
const shutter = $('.bkt-logos-shutter');
const rec = $('.bkt-logos-rec b');
const hold = $('.bkt-logos-hold');
const uid = Math.random().toString(36).slice(2, 8);
panel.id = 'bkt-logos-panel-' + uid;
tabs.forEach((t, i) => { t.id = 'bkt-logos-tab-' + uid + '-' + i; t.setAttribute('aria-controls', panel.id); });
panel.setAttribute('aria-labelledby', tabs[0].id);

let cur = 0, tok = 0, held = false;
const pad = (n) => String(n).padStart(2, '0');
const SNAP = 'cubic-bezier(.7, 0, .3, 1)';

function fill(i) {
  const d = DATA[i];
  $('.bkt-logos-num').textContent = pad(i + 1);
  $('.bkt-logos-q p').textContent = d.q;
  const by = $('.bkt-logos-by');
  by.replaceChildren();
  const b = document.createElement('b'); b.textContent = d.who;
  const co = document.createElement('span'); co.className = 'bkt-logos-co'; co.textContent = d.word;
  by.append(b, ' / ' + d.role + ', ', co);
  $('.bkt-logos-ml').textContent = d.metric;
  $('.bkt-logos-mv s').textContent = d.a;
  $('.bkt-logos-mv b').textContent = d.b;
  $('.bkt-logos-md').textContent = d.delta;
}

// A hard-edged shutter wipes across the panel; the content swaps while it is closed.
function select(i, user) {
  i = (i + DATA.length) % DATA.length;
  if (i === cur) return;
  cur = i;
  tabs.forEach((t, k) => { const on = k === i; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; });
  rec.textContent = pad(i + 1);
  panel.setAttribute('aria-labelledby', tabs[i].id);
  panel.setAttribute('aria-live', user ? 'polite' : 'off');
  if (reduce.matches) { fill(i); return; }
  const t = ++tok;
  shutter.getAnimations().forEach((a) => a.cancel());
  const close = shutter.animate([{ transform: 'scaleX(0)', transformOrigin: '0 50%' }, { transform: 'scaleX(1)', transformOrigin: '0 50%' }], { duration: 230, easing: SNAP, fill: 'forwards' });
  close.finished.then(() => {
    if (t !== tok) return;
    fill(i);
    shutter.animate([{ transform: 'scaleX(1)', transformOrigin: '100% 50%' }, { transform: 'scaleX(0)', transformOrigin: '100% 50%' }], { duration: 320, easing: SNAP });
    close.cancel();
    const parts = [$('.bkt-logos-num'), $('.bkt-logos-q'), $('.bkt-logos-by'), $('.bkt-logos-metric')];
    parts.forEach((el, k) => el.animate(
      [{ clipPath: 'inset(0 100% 0 0)', transform: 'translateX(-12px)' }, { clipPath: 'inset(0 0 0 0)', transform: 'none' }],
      { duration: 420, delay: 120 + k * 60, easing: 'steps(6, end)', fill: 'backwards' }
    ));
  }, () => {});
}

root.addEventListener('animationend', (e) => {
  if (e.animationName === 'bkt-logos-run' && !held) select(cur + 1, false);
});
list.addEventListener('click', (e) => { const t = e.target.closest('.bkt-logos-tab'); if (t) select(tabs.indexOf(t), true); });

// arrows walk the logo grid in two dimensions: up/down jump a whole row
list.addEventListener('keydown', (e) => {
  const cols = tabs.filter((t) => t.offsetTop === tabs[0].offsetTop).length || 1;
  const m = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: cols, ArrowUp: -cols };
  let n = null;
  if (e.key in m) {
    n = cur + m[e.key];
    if (cols >= tabs.length && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) n = cur + (e.key === 'ArrowDown' ? 1 : -1);
    if (n < 0 || n >= tabs.length) n = (n + tabs.length) % tabs.length;
  } else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = tabs.length - 1;
  if (n === null) return;
  e.preventDefault();
  select(n, true);
  tabs[cur].focus();
});

hold.addEventListener('click', () => {
  held = !held;
  root.classList.toggle('is-held', held);
  hold.setAttribute('aria-label', held ? 'Resume rotation' : 'Pause rotation');
  hold.querySelector('span').textContent = held ? 'Play' : 'Pause';
});

let onScreen = false;
const sync = () => root.classList.toggle('is-off', !onScreen || document.hidden);
const io = new IntersectionObserver((es) => { onScreen = es[es.length - 1].isIntersecting; sync(); });
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); io.disconnect(); return; }
  sync();
};
document.addEventListener('visibilitychange', onVis);

css:
.bkt-ratings {
  --bkt-ratings-bg: oklch(99.1% 0.003 250);
  --bkt-ratings-ink: oklch(22% 0.014 260);
  --bkt-ratings-star: oklch(80% 0.155 78);
  --bkt-ratings-accent: oklch(50% 0.09 190);
  --bkt-ratings-muted: color-mix(in oklch, var(--bkt-ratings-ink) 56%, var(--bkt-ratings-bg));
  --bkt-ratings-line: color-mix(in oklch, var(--bkt-ratings-ink) 9%, transparent);
  --bkt-ratings-soft: color-mix(in oklch, var(--bkt-ratings-ink) 4%, var(--bkt-ratings-bg));
  --bkt-ratings-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  container-name: bkt-ratings;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkt-ratings-bg);
  color: var(--bkt-ratings-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkt-ratings-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol, dl, dd, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
}
.bkt-ratings-in {
  display: grid; gap: 36px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "sum" "main";
  padding: clamp(36px, 6.5cqi, 84px) clamp(16px, 5cqi, 64px);
}

.bkt-ratings-sum { grid-area: sum; display: grid; gap: 22px; align-content: start; }
.bkt-ratings-brand {
  display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 600; color: var(--bkt-ratings-accent);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bkt-ratings-title { font-size: clamp(24px, 1.6cqi + 17px, 34px); font-weight: 600; letter-spacing: -.028em; line-height: 1.1; text-wrap: balance; max-width: 18ch; }
.bkt-ratings-score { display: flex; align-items: center; gap: 18px; padding-block: 4px 2px; }
.bkt-ratings-avg {
  display: grid; line-height: .9;
  & b { font-size: clamp(64px, 4cqi + 44px, 84px); font-weight: 250; letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; color: var(--bkt-ratings-muted); margin-top: 8px; }
}
.bkt-ratings-of { display: grid; gap: 8px; font-size: 13px; color: var(--bkt-ratings-muted); line-height: 1.4; & b { color: var(--bkt-ratings-ink); font-weight: 650; font-variant-numeric: tabular-nums; } }
.bkt-ratings-starbox { position: relative; display: block; width: 124px; height: 23px; }
.bkt-ratings-stars { display: block; width: 124px; height: 23px; fill: var(--bkt-ratings-line); }
.bkt-ratings-gold {
  position: absolute; inset: 0 auto 0 0; width: var(--fill); overflow: hidden;
  & .bkt-ratings-stars { fill: var(--bkt-ratings-star); }
}

.bkt-ratings-dist { list-style: none; display: grid; gap: 2px; }
.bkt-ratings-bar {
  width: 100%;
  display: grid; grid-template-columns: 34px minmax(0, 1fr) 82px; align-items: center; gap: 12px;
  font: inherit; color: inherit; text-align: left;
  background: transparent; border: 0; border-radius: 10px;
  padding: 7px 8px; cursor: pointer;
  transition: background-color .25s, opacity .3s var(--bkt-ratings-out);
  &:hover { background: var(--bkt-ratings-soft); }
  &:focus-visible { outline: 2px solid var(--bkt-ratings-accent); outline-offset: 1px; }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--bkt-ratings-accent) 9%, var(--bkt-ratings-bg)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkt-ratings-accent) 35%, transparent); }
}
.bkt-ratings-dist:has([aria-pressed="true"]) .bkt-ratings-bar:not([aria-pressed="true"]) { opacity: .45; }
.bkt-ratings-bk {
  display: inline-flex; align-items: center; gap: 4px; font-weight: 600; font-size: 14px; font-variant-numeric: tabular-nums;
  & svg { width: 13px; height: 13px; fill: var(--bkt-ratings-star); }
}
.bkt-ratings-track { height: 8px; border-radius: 99px; background: var(--bkt-ratings-line); overflow: hidden; }
.bkt-ratings-fill {
  display: block; height: 100%; border-radius: inherit;
  background: var(--bkt-ratings-star);
  transform: scaleX(var(--v)); transform-origin: 0 50%;
  transition: transform 1s var(--bkt-ratings-out) calc(var(--i) * 70ms), background-color .3s;
}
.bkt-ratings-bar[aria-pressed="true"] .bkt-ratings-fill { background: var(--bkt-ratings-accent); }
.bkt-ratings.is-armed .bkt-ratings-fill { transform: scaleX(0); }
.bkt-ratings-bn {
  display: flex; justify-content: space-between; align-items: baseline; gap: 6px;
  font-variant-numeric: tabular-nums;
  & b { font-weight: 600; font-size: 13.5px; }
  & small { font-size: 12px; color: var(--bkt-ratings-muted); }
}
.bkt-ratings-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkt-ratings-subs {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 20px;
  padding-top: 18px; border-top: 1px solid var(--bkt-ratings-line);
  & dt { font-size: 12.5px; color: var(--bkt-ratings-muted); }
  & dd { display: flex; align-items: center; gap: 10px; }
  & dd > span { flex: 1; height: 4px; border-radius: 4px; background: var(--bkt-ratings-line); overflow: hidden; }
  & i { display: block; height: 100%; background: var(--bkt-ratings-ink); transform: scaleX(var(--v)); transform-origin: 0 50%; transition: transform 1s var(--bkt-ratings-out) calc(300ms + var(--i) * 70ms); }
  & b { font-size: 14px; font-weight: 650; font-variant-numeric: tabular-nums; }
}
.bkt-ratings.is-armed .bkt-ratings-subs i { transform: scaleX(0); }

.bkt-ratings-main { grid-area: main; display: grid; gap: 12px; min-width: 0; align-content: start; }
.bkt-ratings-tools { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; }
.bkt-ratings-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--bkt-ratings-soft); border: 1px solid var(--bkt-ratings-line);
  & legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  & label { position: relative; cursor: pointer; }
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & span { display: block; padding: 6px 12px; border-radius: 7px; font-size: 13px; font-weight: 550; color: var(--bkt-ratings-muted); transition: background-color .25s, color .25s, box-shadow .25s; }
  & label:has(input:checked) span { background: var(--bkt-ratings-bg); color: var(--bkt-ratings-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--bkt-ratings-ink) 14%, transparent), 0 0 0 1px var(--bkt-ratings-line); }
  & label:has(input:focus-visible) span { outline: 2px solid var(--bkt-ratings-accent); outline-offset: 1px; }
}
.bkt-ratings-chk { display: inline-flex; align-items: center; gap: 7px; font-size: 13px; color: var(--bkt-ratings-muted); cursor: pointer; & input { width: 16px; height: 16px; margin: 0; } }
.bkt-ratings-status { font-size: 13px; color: var(--bkt-ratings-muted); font-variant-numeric: tabular-nums; & b { color: var(--bkt-ratings-ink); font-weight: 600; } & button { font: inherit; color: var(--bkt-ratings-accent); background: none; border: 0; padding: 0; margin-left: 6px; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; } & button:focus-visible { outline: 2px solid var(--bkt-ratings-accent); outline-offset: 2px; border-radius: 3px; } }

.bkt-ratings-list {
  list-style: none;
  max-height: 520px; overflow-y: auto; overscroll-behavior: contain;
  display: grid; gap: 10px; align-content: start;
  padding: 2px 6px 24px 2px; margin-right: -6px;
  scrollbar-width: thin; scrollbar-color: var(--bkt-ratings-line) transparent;
  -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 36px), transparent);
  mask-image: linear-gradient(to bottom, #000 calc(100% - 36px), transparent);
  &:focus-visible { outline: 2px solid var(--bkt-ratings-accent); outline-offset: 4px; border-radius: 8px; }
}
.bkt-ratings-rev {
  display: grid; gap: 8px;
  padding: 16px 18px;
  border: 1px solid var(--bkt-ratings-line); border-radius: 14px;
  background: var(--bkt-ratings-bg);
  & h3 { font-size: 15.5px; font-weight: 640; letter-spacing: -.012em; line-height: 1.3; text-wrap: balance; }
  & p { font-size: 14.5px; line-height: 1.55; text-wrap: pretty; }
}
.bkt-ratings-rtop { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 12.5px; color: var(--bkt-ratings-muted); font-variant-numeric: tabular-nums; }
.bkt-ratings-mini { display: flex; gap: 2px; & svg { width: 14px; height: 14px; fill: var(--bkt-ratings-line); } & svg.is-on { fill: var(--bkt-ratings-star); } }
.bkt-ratings-rfoot { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 12.5px; color: var(--bkt-ratings-muted); }
.bkt-ratings-help {
  display: inline-flex; align-items: center; gap: 6px;
  font: inherit; font-size: 12.5px; color: var(--bkt-ratings-muted); font-variant-numeric: tabular-nums;
  background: transparent; border: 1px solid var(--bkt-ratings-line); border-radius: 99px;
  padding: 4px 10px 4px 8px; cursor: pointer;
  transition: color .2s, border-color .2s, background-color .2s;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s cubic-bezier(.34, 1.56, .64, 1); }
  &:hover { color: var(--bkt-ratings-ink); border-color: color-mix(in oklch, var(--bkt-ratings-ink) 25%, transparent); }
  &[aria-pressed="true"] { color: var(--bkt-ratings-accent); border-color: color-mix(in oklch, var(--bkt-ratings-accent) 45%, transparent); background: color-mix(in oklch, var(--bkt-ratings-accent) 7%, transparent); }
  &[aria-pressed="true"] svg { rotate: -14deg; fill: color-mix(in oklch, var(--bkt-ratings-accent) 20%, transparent); }
  &:focus-visible { outline: 2px solid var(--bkt-ratings-accent); outline-offset: 2px; }
}
.bkt-ratings-reply {
  margin-top: 2px; padding: 10px 12px; border-radius: 10px;
  background: var(--bkt-ratings-soft);
  border-left: 3px solid var(--bkt-ratings-accent);
  font-size: 13.5px;
  & b { display: block; font-size: 12px; font-weight: 650; color: var(--bkt-ratings-accent); margin-bottom: 2px; }
}
.bkt-ratings.no-replies .bkt-ratings-reply { display: none; }

/* each review rises in as it enters the list's own scrollport */
@supports (animation-timeline: view()) {
  .bkt-ratings-rev {
    animation: bkt-ratings-rise linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 70%;
  }
  @keyframes bkt-ratings-rise {
    from { opacity: 0; transform: translateY(22px) scale(.97); }
    to { opacity: 1; transform: none; }
  }
}

@container bkt-ratings (min-width: 520px) {
  .bkt-ratings-subs { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container bkt-ratings (min-width: 900px) {
  .bkt-ratings-in {
    grid-template-columns: minmax(300px, 380px) minmax(0, 1fr);
    grid-template-areas: "sum main";
    column-gap: clamp(36px, 5cqi, 72px);
  }
  .bkt-ratings-subs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkt-ratings-list { max-height: none; height: 600px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkt-ratings-rev { animation: none; }
  .bkt-ratings-fill, .bkt-ratings-subs i { transition: none; }
  .bkt-ratings.is-armed .bkt-ratings-fill { transform: scaleX(var(--v)); }
  .bkt-ratings.is-armed .bkt-ratings-subs i { transform: scaleX(var(--v)); }
  .bkt-ratings-help svg { transition: none; }
}

