const D = {"dist": {"5": 1642, "4": 451, "3": 128, "2": 54, "1": 41}, "total": 2316, "reviews": [{"s": 5, "t": "Finally, a notes app that gets out of the way", "b": "I have tried them all. Larkspur is the first one where I open it and just write. Search finds things I only half remember, and sync has been flawless across my Mac and iPad for eight months.", "n": "Noor A.", "dev": "Mac & iPad", "d": "2026-08-21", "h": 128}, {"s": 5, "t": "The daily note changed my mornings", "b": "One page per day, with yesterday’s unfinished checklist carried over for me. It is such a small thing, and it is the reason I stuck with it.", "n": "Callum R.", "dev": "iPhone", "d": "2026-09-14", "h": 74}, {"s": 5, "t": "Worth it for the export alone", "b": "I was nervous about lock-in. Export gave me a clean folder of Markdown files with my tags kept as front matter. Knowing I can leave is exactly why I stay.", "n": "Jo-Ann M.", "dev": "Windows", "d": "2026-07-03", "h": 51}, {"s": 4, "t": "Lovely, but I want nested tags", "b": "Fast, quiet, and the editor is a joy. Tags are flat for now, which gets messy past a couple of hundred notes. Still my daily driver.", "n": "Sebastián V.", "dev": "Android", "d": "2026-09-02", "h": 39}, {"s": 4, "t": "Great on desktop, good on phone", "b": "The phone app takes a beat longer to open than the desktop one. Once it is open, it is excellent.", "n": "Mira K.", "dev": "iPhone", "d": "2026-08-09", "h": 22}, {"s": 3, "t": "Pretty, but two sync conflicts", "b": "Both times it kept the two versions side by side so nothing was lost, but I had to merge them by hand.", "n": "Dev P.", "dev": "Linux", "d": "2026-06-18", "h": 17, "r": "Thanks, Dev. Version 5.3 merges paragraph-level edits automatically — we would love to hear whether it fixes this for you."}, {"s": 3, "t": "Missing a web clipper", "b": "I save a lot of articles. Until there is a clipper I keep a second app around just for that, which defeats the point a little.", "n": "Hollis T.", "dev": "Mac", "d": "2026-08-27", "h": 12}, {"s": 2, "t": "The yearly price went up", "b": "I still like the app, but the yearly plan went from $36 to $48 and that stings for a notes app.", "n": "Ana G.", "dev": "iPad", "d": "2026-09-20", "h": 30, "r": "Completely fair, Ana. Anyone subscribed before the change keeps $36 a year for as long as they stay — it shows under Settings › Plan."}, {"s": 1, "t": "Lost my tables on import", "b": "Imported 900 notes from my old app and every table came through as plain text. I spent an evening fixing them.", "n": "Pete W.", "dev": "Windows", "d": "2026-05-11", "h": 9, "r": "Sorry, Pete. Table import shipped in 5.2 — re-running the import now keeps them, and support can walk through it with you."}]};
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const $ = (s) => root.querySelector(s);
const list = $('.bkt-ratings-list');
const status = $('.bkt-ratings-status');
const bars = [...root.querySelectorAll('.bkt-ratings-bar')];
const WORD = { 5: 'five', 4: 'four', 3: 'three', 2: 'two', 1: 'one' };
const STAR = '<path d="M10 1.6l2.5 5.2 5.7.8-4.1 4 1 5.6L10 14.5l-5.1 2.7 1-5.6-4.1-4 5.7-.8z"/>';
const fmt = (n) => n.toLocaleString('en-US');
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const date = (iso) => { const [y, m, d] = iso.split('-').map(Number); return d + ' ' + MON[m - 1] + ' ' + y; };

// unique radio group per mounted copy
const group = 'bkt-ratings-' + Math.random().toString(36).slice(2, 8);
root.querySelectorAll('.bkt-ratings-seg input').forEach((i) => { i.name = group; });

let star = 0, sort = 'helpful';
const voted = new Set();

function item(r, k) {
  const mini = [1, 2, 3, 4, 5].map((s) => '<svg viewBox="0 0 20 19" class="' + (s <= r.s ? 'is-on' : '') + '">' + STAR + '</svg>').join('');
  const helpful = r.h + (voted.has(r) ? 1 : 0);
  return '<li class="bkt-ratings-rev" data-k="' + k + '">' +
    '<div class="bkt-ratings-rtop"><span class="bkt-ratings-mini" role="img" aria-label="' + r.s + ' out of 5 stars">' + mini + '</span><time datetime="' + r.d + '">' + date(r.d) + '</time></div>' +
    '<h3>' + esc(r.t) + '</h3><p>' + esc(r.b) + '</p>' +
    (r.r ? '<div class="bkt-ratings-reply"><b>Reply from the Larkspur team</b>' + esc(r.r) + '</div>' : '') +
    '<div class="bkt-ratings-rfoot"><span>' + esc(r.n) + ' · ' + esc(r.dev) + '</span>' +
    '<button class="bkt-ratings-help" type="button" aria-pressed="' + voted.has(r) + '"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10.5v9H4.5v-9zM7 10.5l3.8-6.3c1.5 0 2.4 1.1 2.1 2.6l-.6 3.2h5.6c1.3 0 2.2 1.2 1.9 2.4l-1.6 5.6c-.3.9-1.1 1.5-2 1.5H7"/></svg>Helpful <span>' + fmt(helpful) + '</span></button></div>' +
    '</li>';
}

function render(animate) {
  const rows = D.reviews.filter((r) => !star || r.s === star)
    .sort((a, b) => sort === 'new' ? b.d.localeCompare(a.d) : (b.h + voted.has(b)) - (a.h + voted.has(a)));
  list.innerHTML = rows.map((r) => item(r, D.reviews.indexOf(r))).join('');
  list.scrollTop = 0;
  const pool = star ? D.dist[star] : D.total;
  status.innerHTML = '<b>' + rows.length + '</b> of ' + fmt(pool) + ' ' + (star ? WORD[star] + '-star ' : '') + 'reviews shown, ' +
    (sort === 'new' ? 'newest first' : 'most helpful first') + (star ? '<button type="button" class="bkt-ratings-clear">Show all ratings</button>' : '');
  if (animate && !reduce.matches) {
    [...list.children].forEach((el, i) => el.animate(
      [{ opacity: 0, translate: '0 14px' }, { opacity: 1, translate: '0 0' }],
      { duration: 460, delay: i * 55, easing: 'cubic-bezier(.16, 1, .3, 1)', fill: 'backwards' }
    ));
  }
}

function setStar(s) {
  star = star === s ? 0 : s;
  bars.forEach((b) => b.setAttribute('aria-pressed', String(Number(b.dataset.s) === star)));
  render(true);
}

root.addEventListener('click', (e) => {
  const bar = e.target.closest('.bkt-ratings-bar');
  if (bar) { setStar(Number(bar.dataset.s)); return; }
  if (e.target.closest('.bkt-ratings-clear')) { setStar(star); bars[0].focus(); return; }
  const help = e.target.closest('.bkt-ratings-help');
  if (help) {
    const r = D.reviews[Number(help.closest('.bkt-ratings-rev').dataset.k)];
    voted.has(r) ? voted.delete(r) : voted.add(r);
    help.setAttribute('aria-pressed', String(voted.has(r)));
    help.querySelector('span').textContent = fmt(r.h + (voted.has(r) ? 1 : 0));
  }
});

// arrow keys move between the five distribution rows
$('.bkt-ratings-dist').addEventListener('keydown', (e) => {
  const i = bars.indexOf(document.activeElement);
  if (i < 0) return;
  let n = null;
  if (e.key === 'ArrowDown') n = Math.min(bars.length - 1, i + 1);
  else if (e.key === 'ArrowUp') n = Math.max(0, i - 1);
  else if (e.key === 'Escape' && star) { e.preventDefault(); setStar(star); return; }
  if (n === null) return;
  e.preventDefault();
  bars[n].focus();
});

root.addEventListener('change', (e) => {
  if (e.target.name === group) { sort = e.target.value; render(true); }
  else if (e.target.type === 'checkbox') root.classList.toggle('no-replies', !e.target.checked);
});

render(false);

// distribution bars grow in the first time the section is seen
if (!reduce.matches) {
  root.classList.add('is-armed');
  const io = new IntersectionObserver((es) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (!es[es.length - 1].isIntersecting) return;
    io.disconnect();
    requestAnimationFrame(() => {
      if (!root.isConnected) return;
      root.classList.remove('is-armed');
    });
  }, { threshold: 0.2 });
  io.observe(root);
}
